      "path": "packages/boot/app-boot/src/profile.ts",
      "content": "/**\n * Profile discovery, initialization, and patch-layer composition for the\n * `dsh --profile` launcher family.\n *\n * A profile is a directory under `$DSH_HOME/profiles/<name>` holding a\n * `package.json` (out-of-tree plugin dependencies plus the profile manifest\n * `dsh.profile` with its ordered `bundles` list) and a `cordis.patch.yml`\n * (the user's own patch layer, applied after every bundle layer). Bundles are\n * npm packages whose manifest declares\n * `\"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }` (one file, or an\n * ordered list of files); the tree is composed by applying each bundle's patch\n * lists in `dsh.profile.bundles` order over an empty entry list, then the\n * profile's own patches, then any launcher layers (`--patch` files and\n * flag-derived patches).\n *\n * Module resolution is two-anchor by construction: a bundle name resolves\n * first from the dsh installation (the launcher's own package), then from the\n * profile directory. Pnpm-managed entries in the profile's `node_modules`\n * resolve first. The runtime resolution supplies packages carried by the\n * installation and selected bundles to Node's ESM and CommonJS resolvers.\n * @module @deepseek-ai/dsh-app-boot/profile\n */\n\nimport { createRequire } from 'node:module'\nimport { existsSync, mkdirSync, readdirSync, readFileSync, readlinkSync, realpathSync, rmSync, statSync, unlinkSync, writeFileSync } from 'node:fs'\nimport { basename, dirname, join, relative, resolve, sep } from 'node:path'\nimport type { EntryOptions } from '@deepseek-ai/cordis-plugin-loader'\nimport { applyEntryPatches, type PatchOptions } from '@deepseek-ai/cordis-plugin-include'\nimport { resolveDshHome } from '@deepseek-ai/dsh-home-paths'\nimport type { DshBundleManifest, DshPackageManifest } from '@deepseek-ai/dsh-package-manifest'\nimport { INSTALLATION_OWNED_PROFILE_TUPLES, PROFILE_TEMPLATES, RETIRED_BUNDLES } from '@deepseek-ai/dsh-official-bundles'\nimport { assertBundlePlatform } from './bundle-platform.ts'\nimport { evaluatePluginCompatibility, pluginCompatibilityWarning } from './plugin-compatibility.ts'\nimport { readProfileVersionExemptions } from './profile-compatibility.ts'\nimport { loadOverlayPatches } from './index.ts'\nimport { realModuleDirectory } from './profile-resolution/legacy-links.ts'\n\n/** Directory under the Harness home holding every profile. */\nexport const PROFILES_DIR = 'profiles'\n\n/** The user patch layer inside a profile directory (hot-reloaded on long-lived surfaces). */\nexport const PROFILE_PATCH_FILENAME = 'cordis.patch.yml'\n\n/** Package metadata accepted by the profile reader; local profiles need no published identity. */\nexport type ProfileManifest = Partial<DshPackageManifest>\n\n/**\n * The patch files a bundle declares, as written: one file for a string\n * `patch`, the listed files in order for an array.\n * @param bundle - the bundle's `dsh.bundle` declaration, as read from package.json.\n * @returns the package-relative patch file paths in application order.\n * @throws {Error} when `patch` is neither a string nor a list of strings.\n */\nexport function bundlePatchFiles(bundle: DshBundleManifest): string[] {\n  const declared = typeof bundle.patch === 'string' ? [bundle.patch] : bundle.patch\n  if (!Array.isArray(declared) || !declared.every(file => typeof file === 'string')) {\n    throw new Error('dsh.bundle.patch must be a file path or a list of file paths')\n  }\n  return declared\n}\n\n/**\n * Resolve a bundle declaration to its ordered absolute patch files.\n * @param packageDir - absolute directory of the bundle package.\n * @param bundle - the bundle's `dsh.bundle` declaration, as read from package.json.\n * @returns the absolute patch file paths in application order.\n * @throws {Error} when `patch` is neither a string nor a list of strings.\n */\nexport function bundlePatchPaths(packageDir: string, bundle: DshBundleManifest): string[] {\n  return bundlePatchFiles(bundle).map(file => join(packageDir, file))\n}\n\n/** One resolved bundle layer of a profile. */\nexport interface ProfileLayer {\n  /** The bundle's package name, as listed in `dsh.profile.bundles`. */\n  packageName: string\n  /** Absolute directory of the resolved bundle package. */\n  packageDir: string\n  /** Absolute paths of the bundle's patch files, in application order. */\n  patchPaths: readonly string[]\n  /** The parsed patch lists of every file, concatenated in application order. */\n  patches: PatchOptions[]\n}\n\n/** A loaded profile: resolved bundle layers plus the user's own patch layer. */\nexport interface Profile {\n  /** The profile name (its directory basename). */\n  name: string\n  /** Absolute profile directory. */\n  dir: string\n  /** Bundle layers in `dsh.profile.bundles` order. */\n  layers: ProfileLayer[]\n  /** Absolute path of the profile's own patch file. */\n  patchPath: string\n  /** The profile's own patches; empty when the file is absent. */\n  patches: PatchOptions[]\n  /** Selected bundles that contributed no layer, in `dsh.profile.bundles` order, with why. */\n  skippedBundles: SkippedBundle[]\n}\n\n/** A selected bundle the profile could not load, or whose own DSH requirements the profile does not exempt. */\nexport interface SkippedBundle {\n  /** The bundle's package name from `dsh.profile.bundles`. */\n  packageName: string\n  /** The resolution, manifest, compatibility, or patch-loading failure. */\n  reason: string\n}\n\n/**\n * Print each skipped bundle once; loading never prints, so launchers call this once per start.\n * @param binName - the diagnostic prefix.\n * @param profile - the loaded profile.\n */\nexport function reportSkippedBundles(binName: string, profile: Pick<Profile, 'skippedBundles'>): void {\n  for (const { packageName, reason } of profile.skippedBundles) {\n    process.stderr.write(`${binName}: skipping profile bundle ${JSON.stringify(packageName)}: ${reason}\\n`)\n  }\n}\n\n/** One package the runtime resolution supplies at the interception layer. */\nexport interface RuntimeResolutionEntry {\n  /** Bare package name. */\n  readonly name: string\n  /** Package directory selected by the existing dependency traversal. */\n  readonly packageDir: string\n  /** Selected package version when its manifest declares one. */\n  readonly version: string | undefined\n  /** Manifest whose dependency edge selected this package. */\n  readonly declarer: string\n  /** Whether every profile or only the active profile receives this entry. */\n  readonly scope: 'installation' | 'profile'\n}\n\n/**\n * A profile node_modules entry linked to a directory outside the shared profiles tree and the active profile.\n * Importers below `realPath` use Node's real ancestor chain, with peer mappings read at each node_modules position.\n */\nexport interface LinkedRoot {\n  /** Package name of the profile `node_modules` entry, including its scope. */\n  readonly name: string\n  /** Real directory outside the shared profiles tree and active profile; a package.json is optional. */\n  readonly realPath: string\n}\n\n/** Complete immutable package table for one profile launch. */\nexport interface RuntimeResolution {\n  /** Directory containing every profile; its node_modules is the interception layer. */\n  readonly profilesDir: string\n  /** Active profile directory, when profile-scope entries were included. */\n  readonly profileDir: string | undefined\n  /** Profile-declared packages installed in the profile's own node_modules. */\n  readonly localPackageNames: readonly string[]\n  /** Installation-scope entries followed by profile-scope entries in precedence order. */\n  readonly entries: readonly RuntimeResolutionEntry[]\n  /** Active profile links to external directories, sorted by name. */\n  readonly linkedRoots: readonly LinkedRoot[]\n}\n\n/**\n * Resolve a profile's directory under the Harness home.\n * @param name - the profile name (`dsh --profile <name>`).\n * @param home - the Harness home; defaults to {@link resolveDshHome}.\n * @returns the absolute profile directory (which may not exist yet).\n */\nexport function resolveProfileDir(name: string, home: string = resolveDshHome()): string {\n  if (name === '' || name.includes('/') || name.includes('\\\\') || name === '.' || name === '..'\n    // Node reserves this name for dependency lookup.\n    || name === 'node_modules') {\n    throw new Error(`dsh: invalid profile name ${JSON.stringify(name)}`)\n  }\n  return join(home, PROFILES_DIR, name)\n}\n\nconst PROFILE_PATCH_TEMPLATE = `# Your patch layer for this dsh profile, applied after every bundle layer:\n# a top-level YAML array of loader patch entries (id-targeted config\n# overrides, disables, and insert lists; \\`!!js\\` expressions allowed).\n[]\n`\n\n// The hoisted linker gives out-of-tree plugins a flat node_modules whose\n// missing peers (cordis and friends) use the runtime resolution, so every plugin shares the\n// installation's single cordis instance instead of a duplicate. pnpm ≥10\n// reads its settings from pnpm-workspace.yaml, not .npmrc.\nconst PROFILE_PNPM_WORKSPACE = `packages:\n  - .\n\nnodeLinker: hoisted\nautoInstallPeers: false\n`\n\n/**\n * Initialize a profile directory: manifest, empty user patch layer, and the\n * pnpm settings out-of-tree plugins need. Existing files are never touched,\n * so re-running is a no-op on an initialized profile.\n * @param dir - the profile directory from {@link resolveProfileDir}.\n * @param bundles - the initial `dsh.profile.bundles` layer list.\n */\nexport function initProfile(\n  dir: string,\n  bundles: readonly string[],\n): void {\n  mkdirSync(dir, { recursive: true })\n  const manifestPath = join(dir, 'package.json')\n  if (!existsSync(manifestPath)) {\n    const manifest: ProfileManifest & { private: boolean } = {\n      name: `dsh-profile-${basename(dir)}`,\n      private: true,\n      dependencies: {},\n      dsh: { profile: { bundles: [...bundles] } },\n    }\n    writeFileSync(manifestPath, JSON.stringify(manifest, undefined, 2) + '\\n')\n  }\n  const patchPath = join(dir, PROFILE_PATCH_FILENAME)\n  if (!existsSync(patchPath)) writeFileSync(patchPath, PROFILE_PATCH_TEMPLATE)\n  const workspacePath = join(dir, 'pnpm-workspace.yaml')\n  if (!existsSync(workspacePath)) writeFileSync(workspacePath, PROFILE_PNPM_WORKSPACE)\n}\n\n/** Directory where the link backend of the dsh 0.1.5 releases projected bundle-carried packages into a profile. */\nconst LINK_PROJECTION_DIR = '.dsh-module-fallback'\n\n/**\n * Remove the package projections a link-backend launch left in a profile.\n * Only symlinks under the profile's `node_modules` whose target lies inside\n * `<profile>/.dsh-module-fallback/node_modules` are unlinked, then that directory is removed;\n * pnpm-installed packages and every other symlink stay. A profile without the directory is untouched.\n * @param dir - the profile directory.\n */\nexport function removeLinkProjections(dir: string): void {\n  const owned = join(dir, LINK_PROJECTION_DIR)\n  if (!existsSync(owned)) return\n  const ownedModules = join(owned, 'node_modules')\n  for (const link of symlinksUnder(join(dir, 'node_modules'))) {\n    if (pointsInto(link, ownedModules)) unlinkSync(link)\n  }\n  rmSync(owned, { recursive: true, force: true })\n}\n\n/** Top-level and scoped entries under a node_modules directory that are symlinks or junctions. */\nfunction symlinksUnder(modules: string): string[] {\n  const links: string[] = []\n  if (!existsSync(modules)) return links\n  for (const entry of readdirSync(modules, { withFileTypes: true })) {\n    const path = join(modules, entry.name)\n    if (entry.isSymbolicLink()) {\n      links.push(path)\n    } else if (entry.name.startsWith('@') && entry.isDirectory()) {\n      for (const child of readdirSync(path, { withFileTypes: true })) {\n        if (child.isSymbolicLink()) links.push(join(path, child.name))\n      }\n    }\n  }\n  return links\n}\n\n/**\n * Active profile `node_modules` entries linked outside the shared profiles tree and the active profile.\n * Missing targets and files are not linked roots; invalid link chains retain Node's diagnostic.\n */\nfunction linkedProfileRoots(profile: Profile, profilesDir: string): LinkedRoot[] {\n  const modules = join(profile.dir, 'node_modules')\n  const links = symlinksUnder(modules)\n  if (links.length === 0) return []\n  let tree: string\n  try {\n    tree = realModuleDirectory(profilesDir) + sep\n  } catch (error) {\n    // A profiles tree that is not materialized yet holds no links.\n    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n    tree = resolve(profilesDir) + sep\n  }\n  const excludedTrees = [tree, realModuleDirectory(profile.dir) + sep]\n  const roots: LinkedRoot[] = []\n  for (const linkPath of links) {\n    let realPath: string\n    try {\n      realPath = realModuleDirectory(linkPath)\n    } catch (error) {\n      // A dangling link is not a package Node can load from the profile.\n      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n      continue\n    }\n    if (excludedTrees.some(prefix => realPath + sep === prefix || realPath.startsWith(prefix))\n      || !statSync(realPath).isDirectory()) continue\n    roots.push({ name: relative(modules, linkPath).split(sep).join('/'), realPath })\n  }\n  return roots.sort((left, right) => left.name.localeCompare(right.name))\n}\n\n/** Whether a symlink's target directory is `root` or lies below it. */\nfunction pointsInto(link: string, root: string): boolean {\n  try {\n    const target = resolve(dirname(link), readlinkSync(link))\n    const parent = realpathSync.native(dirname(target))\n    const rootPath = realpathSync.native(root)\n    return parent === rootPath || parent.startsWith(rootPath + sep)\n  } catch (error) {\n    // A target whose parent no longer exists cannot be one of the projections this launch owns.\n    /* v8 ignore next 2 -- a non-ENOENT realpath failure requires a host filesystem fault */\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false\n    /* v8 ignore next -- see the host-filesystem exception above */\n    throw error\n  }\n}\n\n/** Read one package manifest while traversing a dependency graph. */\nfunction readPackageManifest(anchor: string): ProfileManifest {\n  return JSON.parse(readFileSync(anchor, 'utf8')) as ProfileManifest\n}\n\n/** Return dependency names that may be imported by a loader-visible plugin. */\nfunction profileDependencyNames(manifest: ProfileManifest): string[] {\n  return [...Object.keys(manifest.dependencies ?? {}), ...Object.keys(manifest.peerDependencies ?? {}),\n    ...Object.keys(manifest.optionalDependencies ?? {})]\n}\n\n/** Resolve the installation packages that the runtime resolver supplies to every profile. */\nfunction collectInstallationScopePackages(\n  installAnchor: string, skippedBundles: ReadonlySet<string>,\n): {\n  packageNames: ReadonlySet<string>\n  packageDirs: ReadonlyMap<string, string>\n  declarers: ReadonlyMap<string, string>\n  versions: ReadonlyMap<string, string | undefined>\n} {\n  // Real declaring paths keep workspace symlinks under node_modules from disabling tsx path mappings.\n  const canonicalAnchor = join(realModuleDirectory(dirname(installAnchor)), basename(installAnchor))\n  const appManifest = readPackageManifest(canonicalAnchor)\n  const links = new Map<string, string>()\n  const declarers = new Map<string, string>()\n  const versions = new Map<string, string | undefined>()\n  /* v8 ignore next -- a real app manifest always declares its name */\n  if (appManifest.name !== undefined) {\n    // The CLI derives the installation anchor from import.meta.url (already real) and the Desktop Host from its\n    // runtime directory (not a symlink); the directory is kept as given rather than canonicalized here.\n    links.set(appManifest.name, dirname(installAnchor))\n    declarers.set(appManifest.name, canonicalAnchor)\n    versions.set(appManifest.name, appManifest.version)\n  }\n  // BFS over the resolvable dependency graph; the visited set is the link\n  // map itself (first resolution wins, matching Node's own nearest-wins).\n  const queue: { anchor: string; manifest: ProfileManifest }[] = [{ anchor: canonicalAnchor, manifest: appManifest }]\n  for (let next = queue.shift(); next !== undefined; next = queue.shift()) {\n    // Peer dependencies participate: Service Definition packages (dsh-subprocess,\n    // dsh-compaction, ...) are peers of their implementations, never plain\n    // dependencies, yet out-of-tree plugins import them directly.\n    /* v8 ignore next -- a real app manifest always declares dependencies */\n    for (const dep of profileDependencyNames(next.manifest)) {\n      if (links.has(dep)) continue\n      const dir = packageDirFromAnchor(next.anchor, dep)\n      // A declared-but-uninstalled dependency cannot be a loader-visible\n      // plugin; skip it rather than fail the whole boot.\n      if (dir === undefined) continue\n      const manifestPath = join(realModuleDirectory(dir), 'package.json')\n      let manifest: ProfileManifest\n      try {\n        manifest = skippedBundles.has(dep) ? readProfileManifest('dsh', dir) : readPackageManifest(manifestPath)\n      } catch (error) {\n        if (!skippedBundles.has(dep)) throw error\n        continue\n      }\n      links.set(dep, dir)\n      declarers.set(dep, next.anchor)\n      versions.set(dep, manifest.version)\n      queue.push({ anchor: manifestPath, manifest })\n    }\n  }\n  return { packageNames: new Set(links.keys()), packageDirs: links, declarers, versions }\n}\n\n/** Inputs for {@link createRuntimeResolution}. */\nexport interface RuntimeResolutionOptions {\n  /** Absolute package.json path of the running dsh installation. */\n  installAnchor: string\n  /** Loaded profile whose selected bundles may carry profile-local plugins. */\n  profile?: Profile\n  /** Harness home; defaults to {@link resolveDshHome}. */\n  home?: string\n}\n\n/**\n * Compute the runtime resolution without writing module-resolution files.\n * @param options - installation anchor, optional loaded profile, and Harness home.\n * @returns the complete immutable runtime resolution.\n */\nexport async function createRuntimeResolution(\n  options: RuntimeResolutionOptions,\n): Promise<ProfileRuntimeResolution> {\n  const { installAnchor, profile, home = resolveDshHome() } = options\n  const profilesDir = join(home, PROFILES_DIR)\n  const manifest = readOptionalProfileManifest(profile)\n  const { packageNames, packageDirs, declarers, versions } = collectInstallationScopePackages(\n    installAnchor, new Set(profile?.skippedBundles.map(skipped => skipped.packageName)),\n  )\n  const profileDeclarers = new Map<string, string>()\n  const profileVersions = new Map<string, string | undefined>()\n  const localPackageNames = profile === undefined ? [] : installedProfilePackageNames(profile, manifest)\n  const profilePackages: ReadonlyMap<string, string> = profile === undefined\n    ? new Map<string, string>()\n    : collectProfileScopePackages(profile, packageNames, profileDeclarers, profileVersions)\n  const linkedRoots = profile === undefined ? [] : linkedProfileRoots(profile, profilesDir)\n  // The Promise return type is the pre-stable API; construction has no asynchronous step.\n  return await Promise.resolve(new ProfileRuntimeResolution({ installAnchor, profileDir: profile?.dir, home }, {\n    profilesDir,\n    profileDir: profile?.dir,\n    localPackageNames: Object.freeze(localPackageNames),\n    linkedRoots: Object.freeze(linkedRoots.map(root => Object.freeze(root))),\n    entries: Object.freeze([\n      ...[...packageDirs].map(([name, packageDir]) => Object.freeze({\n        name, packageDir, version: versions.get(name),\n        declarer: declarers.get(name) as string, scope: 'installation' as const,\n      })),\n      ...[...profilePackages].map(([name, packageDir]) => Object.freeze({\n        name, packageDir, version: profileVersions.get(name),\n        declarer: profileDeclarers.get(name) as string, scope: 'profile' as const,\n      })),\n    ]),\n  }))\n}\n\n/** Inputs a {@link ProfileRuntimeResolution} reuses to compute its successor. */\ninterface ResolutionSource {\n  installAnchor: string\n  home: string\n  profileDir: string | undefined\n}\n\n/**\n * A runtime resolution that remembers the inputs it was computed from. Worker environment data carries only its\n * fields; the inputs stay private to the thread that computed it.\n */\nexport class ProfileRuntimeResolution implements RuntimeResolution {\n  readonly profilesDir: string\n  readonly profileDir: string | undefined\n  readonly localPackageNames: readonly string[]\n  readonly entries: readonly RuntimeResolutionEntry[]\n  readonly linkedRoots: readonly LinkedRoot[]\n  readonly #source: ResolutionSource\n\n  /**\n   * @param source - inputs of {@link createRuntimeResolution}, reused by {@link computeLatestResolution}.\n   * @param table - the computed package table.\n   */\n  constructor(source: ResolutionSource, table: RuntimeResolution) {\n    this.#source = source\n    this.profilesDir = table.profilesDir\n    this.profileDir = table.profileDir\n    this.localPackageNames = table.localPackageNames\n    this.entries = table.entries\n    this.linkedRoots = table.linkedRoots\n    Object.freeze(this)\n  }\n\n  /**\n   * Compute the latest generation from the same installation, profile directory, and Harness home, rereading the\n   * profile's manifest, bundle selection, and installed packages from disk, without retaining synthetic layers.\n   * With no profile directory, only installation packages are recomputed. This instance is unchanged.\n   * @returns a new resolution for the latest generation.\n   */\n  computeLatestResolution(): Promise<ProfileRuntimeResolution> {\n    const { installAnchor, home, profileDir } = this.#source\n    return createRuntimeResolution({\n      installAnchor, home,\n      ...profileDir === undefined ? {} : { profile: loadProfileDirectory('dsh', profileDir, installAnchor) },\n    })\n  }\n}\n\n/** Synthetic profiles used by direct callers may have no on-disk manifest. */\nfunction readOptionalProfileManifest(profile: Profile | undefined): ProfileManifest | undefined {\n  if (profile === undefined) return undefined\n  try {\n    return readPackageManifest(join(profile.dir, 'package.json'))\n  } catch (error) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined\n    throw error\n  }\n}\n\n/** Return installed direct dependencies that Node resolves before profile fallback. */\nfunction installedProfilePackageNames(profile: Profile, manifest: ProfileManifest | undefined): string[] {\n  if (manifest === undefined) return []\n  return profileDependencyNames(manifest)\n    .filter(name => existsSync(join(profile.dir, 'node_modules', name, 'package.json')))\n}\n\n/** Collect the first resolvable package directory for each dependency name. */\nfunction dependencyClosure(\n  anchors: readonly string[], reserved: ReadonlySet<string>,\n  declarers?: Map<string, string>,\n  versions?: Map<string, string | undefined>,\n): Map<string, string> {\n  const links = new Map<string, string>()\n  const visited = new Set(reserved)\n  for (const anchor of anchors) {\n    const canonicalAnchor = join(realModuleDirectory(dirname(anchor)), basename(anchor))\n    const manifest = readPackageManifest(canonicalAnchor)\n    /* v8 ignore next -- an installable package manifest always declares its name */\n    if (manifest.name === undefined) continue\n    if (!visited.has(manifest.name)) {\n      visited.add(manifest.name)\n      links.set(manifest.name, dirname(canonicalAnchor))\n      declarers?.set(manifest.name, canonicalAnchor)\n      versions?.set(manifest.name, manifest.version)\n    }\n    const queue: { anchor: string; manifest: ProfileManifest }[] = [{ anchor: canonicalAnchor, manifest }]\n    for (let next = queue.shift(); next !== undefined; next = queue.shift()) {\n      // Service Provider packages commonly expose Service Definitions as peers.\n      /* v8 ignore next -- an installable package manifest always declares dependencies or peers */\n      for (const dep of profileDependencyNames(next.manifest)) {\n        if (visited.has(dep)) continue\n        const dir = packageDirFromAnchor(next.anchor, dep)\n        // A declared-but-uninstalled dependency cannot be loader-visible.\n        if (dir === undefined) continue\n        visited.add(dep)\n        links.set(dep, dir)\n        declarers?.set(dep, next.anchor)\n        const manifestPath = join(realModuleDirectory(dir), 'package.json')\n        const dependencyManifest = readPackageManifest(manifestPath)\n        versions?.set(dep, dependencyManifest.version)\n        queue.push({ anchor: manifestPath, manifest: dependencyManifest })\n      }\n    }\n  }\n  return links\n}\n\n/** Collect packages carried by the profile's selected bundles that the installation does not supply. */\nfunction collectProfileScopePackages(\n  profile: Profile, installationPackageNames: ReadonlySet<string>,\n  declarers?: Map<string, string>,\n  versions?: Map<string, string | undefined>,\n): Map<string, string> {\n  const bundleAnchors = profile.layers\n    .filter(layer => !installationPackageNames.has(layer.packageName))\n    .map(layer => join(layer.packageDir, 'package.json'))\n  const bundleLinks = dependencyClosure(bundleAnchors, installationPackageNames, declarers, versions)\n  for (const layer of profile.layers) bundleLinks.delete(layer.packageName)\n  return bundleLinks\n}\n\n/**\n * Read a profile's manifest.\n * @param binName - the diagnostic prefix on the thrown error.\n * @param dir - the profile directory.\n * @returns the parsed manifest.\n */\nexport function readProfileManifest(binName: string, dir: string): ProfileManifest {\n  const path = join(dir, 'package.json')\n  let raw: string\n  try {\n    raw = readFileSync(path, 'utf8')\n  } catch (error) {\n    throw new Error(`${binName}: failed to read profile manifest ${path}: ${String(error)}`)\n  }\n  // The field checks below validate the file data before trusting the parse type.\n  const parsed = JSON.parse(raw) as ProfileManifest | null\n  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {\n    throw new Error(`${binName}: profile manifest ${path} must hold a JSON object`)\n  }\n  return parsed\n}\n\n/**\n * Write a profile's manifest back (2-space JSON, trailing newline).\n * @param dir - the profile directory.\n * @param manifest - the manifest value to persist.\n */\nexport function writeProfileManifest(dir: string, manifest: ProfileManifest): void {\n  writeFileSync(join(dir, 'package.json'), JSON.stringify(manifest, undefined, 2) + '\\n')\n}\n\n/** Return whether two bundle lists have the same values in the same order. */\nfunction sameBundles(left: readonly string[], right: readonly string[]): boolean {\n  return left.length === right.length && left.every((value, index) => value === right[index])\n}\n\n/** Return `manifest` with `dsh.profile.bundles` replaced, preserving all other fields. */\nfunction withBundles(manifest: ProfileManifest, bundles: readonly string[]): ProfileManifest {\n  return {\n    ...manifest,\n    dsh: {\n      ...manifest.dsh,\n      profile: {\n        ...manifest.dsh?.profile,\n        bundles: [...bundles],\n      },\n    },\n  }\n}\n\n/**\n * Normalize an exact installation-owned bundle tuple to its shipped template,\n * preserving all other manifest fields. Other bundle lists remain untouched.\n */\nfunction normalizeShippedProfile(name: string, dir: string, manifest: ProfileManifest): ProfileManifest {\n  const installationOwned = INSTALLATION_OWNED_PROFILE_TUPLES[name]\n  const template = PROFILE_TEMPLATES[name]\n  const bundles = manifest.dsh?.profile?.bundles\n  if (template === undefined || bundles === undefined) return manifest\n  const isRetiredTuple = installationOwned !== undefined && sameBundles(bundles, installationOwned)\n  if (!isRetiredTuple) return manifest\n  const normalized = withBundles(manifest, template.bundles)\n  writeProfileManifest(dir, normalized)\n  return normalized\n}\n\n/**\n * Remove {@link RETIRED_BUNDLES} from a profile's bundle list, writing the\n * manifest back only when it listed one.\n */\nfunction dropRetiredBundles(dir: string, manifest: ProfileManifest): ProfileManifest {\n  const bundles = manifest.dsh?.profile?.bundles ?? []\n  const kept = bundles.filter(bundle => !RETIRED_BUNDLES.has(bundle))\n  if (kept.length === bundles.length) return manifest\n  const normalized = withBundles(manifest, kept)\n  writeProfileManifest(dir, normalized)\n  return normalized\n}\n\n/**\n * Resolve a package's root directory from one anchor without depending on the\n * package exporting `./package.json` (`require.resolve` would need that):\n * probe the require resolution paths for a directory holding the named\n * manifest. This is Node's own node_modules lookup order, so the result\n * matches what the Loader would import from the same anchor, and\n * `existsSync` follows the symlinks pnpm's isolated layout uses.\n */\nfunction packageDirFromAnchor(anchor: string, packageName: string): string | undefined {\n  // resolve.paths returns null only for builtins, which no bundle name is.\n  /* v8 ignore next */\n  for (const searchPath of createRequire(anchor).resolve.paths(packageName) ?? []) {\n    const candidate = join(searchPath, packageName)\n    if (existsSync(join(candidate, 'package.json'))) return candidate\n  }\n  return undefined\n}\n\n/**\n * Resolve one bundle package's directory: installation anchor first, then the\n * profile directory. The installation-first order is the contract that\n * `@deepseek-ai/dsh-base` (and every other in-box bundle) always comes from\n * the same installation as the running dsh, never from a profile-local copy.\n * Resolution does not require the package to export `./package.json`.\n * @param binName - the diagnostic prefix on the thrown error.\n * @param packageName - the bundle's package name from `dsh.profile.bundles`.\n * @param installAnchor - absolute path of a file inside the dsh app package (its package.json).\n * @param profileDir - the profile directory (second anchor).\n * @returns the bundle package's absolute directory.\n */\nexport function resolveBundleDir(\n  binName: string, packageName: string, installAnchor: string, profileDir: string,\n): string {\n  for (const anchor of [installAnchor, join(profileDir, 'package.json')]) {\n    const dir = packageDirFromAnchor(anchor, packageName)\n    if (dir !== undefined) return dir\n  }\n  throw new Error(\n    `${binName}: cannot resolve profile bundle ${JSON.stringify(packageName)} from the dsh installation or ${profileDir}; `\n    + `run 'dsh plugin --profile ${basename(profileDir)} install' if its dependency is not installed`,\n  )\n}\n\n/**\n * Load an already initialized profile directory without resolving it through\n * the shared Harness home. This is used by application-owned profiles whose\n * package project and lifecycle belong to that application.\n * Retired bundles are removed from the stored bundle list first, rewriting the\n * manifest when it listed one. Unreadable bundles, unsupported Host platforms, and bundles whose own dsh requirements\n * the profile does not exempt are skipped\n * without changing the manifest and listed in `skippedBundles`; nothing is printed.\n * @param binName - the diagnostic prefix on thrown errors.\n * @param dir - absolute profile package directory.\n * @param installAnchor - absolute path of the owning dsh app's package.json.\n * @param options - `userLayer: false` skips reading `cordis.patch.yml`.\n * @returns the successfully loaded bundle layers and optional user patch layer.\n */\nexport function loadProfileDirectory(\n  binName: string,\n  dir: string,\n  installAnchor: string,\n  options: { userLayer?: boolean } = {},\n): Profile {\n  const manifest = dropRetiredBundles(dir, readProfileManifest(binName, dir))\n  const bundles = manifest.dsh?.profile?.bundles ?? []\n  const layers: ProfileLayer[] = []\n  const skippedBundles: SkippedBundle[] = []\n  const exemptions = bundles.length === 0 ? {} : readProfileVersionExemptions(dir)\n  for (const packageName of bundles) {\n    try {\n      const packageDir = resolveBundleDir(binName, packageName, installAnchor, dir)\n      const bundleManifest = readProfileManifest(binName, packageDir)\n      const bundle = bundleManifest.dsh?.bundle\n      if (bundle === undefined) {\n        throw new Error(`${binName}: profile bundle ${JSON.stringify(packageName)} declares no dsh.bundle in its package.json`)\n      }\n      assertBundlePlatform(bundle.platforms, process.platform)\n      // A bundle is not a plugin row, so row admission never reads its own dsh requirements.\n      const issue = evaluatePluginCompatibility(bundleManifest, exemptions)\n      if (issue !== undefined && !issue.exempted) throw new Error(pluginCompatibilityWarning(issue))\n      const patchPaths = bundlePatchPaths(packageDir, bundle)\n      const patches = patchPaths.flatMap(patchPath => loadOverlayPatches(binName, patchPath))\n      layers.push({ packageName, packageDir, patchPaths, patches })\n    } catch (error) {\n      skippedBundles.push({ packageName, reason: String(error) })\n    }\n  }\n  const patchPath = join(dir, PROFILE_PATCH_FILENAME)\n  const patches = options.userLayer !== false && existsSync(patchPath)\n    ? loadOverlayPatches(binName, patchPath)\n    : []\n  return { name: basename(dir), dir, layers, patchPath, patches, skippedBundles }\n}\n\n/**\n * Load a profile: resolve every `dsh.profile.bundles` entry to its patch\n * layer and parse the profile's own patch file. Unreadable bundles, unsupported Host platforms,\n * and incompatible bundles are skipped and listed in `skippedBundles`; profile manifest and user patch errors still throw.\n * @param binName - the diagnostic prefix on thrown errors.\n * @param name - the profile name.\n * @param installAnchor - absolute path of the dsh app's package.json (first resolution anchor).\n * @param home - the Harness home; defaults to {@link resolveDshHome}.\n * @param options - `userLayer: false` skips reading `cordis.patch.yml`, so a\n * bundles-only consumer (`--dump-default-config`, a recovery diagnostic)\n * cannot fail on a broken user layer.\n * @returns the loaded profile (empty `patches` when the user layer is skipped).\n */\nexport function loadProfile(\n  binName: string, name: string, installAnchor: string, home: string = resolveDshHome(),\n  options: { userLayer?: boolean } = {},\n): Profile {\n  const dir = resolveProfileDir(name, home)\n  if (!existsSync(join(dir, 'package.json'))) {\n    const template = PROFILE_TEMPLATES[name]\n    if (template === undefined) {\n      throw new Error(\n        `${binName}: profile ${JSON.stringify(name)} does not exist; create it with 'dsh plugin --profile ${name} add <package>'`,\n      )\n    }\n    initProfile(dir, template.bundles)\n  }\n  removeLinkProjections(dir)\n  normalizeShippedProfile(name, dir, readProfileManifest(binName, dir))\n  return loadProfileDirectory(binName, dir, installAnchor, options)\n}\n\n/**\n * Compose patch layers into the effective entry list over an empty root —\n * the same single `applyEntryPatches` call the boot include makes, so flag\n * derivation and config dumps see exactly what mounts.\n * @param layers - patch lists in application order.\n * @param warn - sink for skipped-patch diagnostics; defaults to silent (boot repeats them).\n * @returns the composed entry list.\n */\nexport function composeEntries(\n  layers: readonly PatchOptions[][], warn: (message: string) => void = () => {},\n): EntryOptions[] {\n  return applyEntryPatches([], structuredClone(layers.flat()), (message: string, ...args: unknown[]) => {\n    let index = 0\n    warn(message.replace(/%C/g, () => JSON.stringify(args[index++])))\n  })\n}\n"
    },
    {
      "path": "packages/bundle/base/cordis.patch.yml",
      "content": "# The dsh-base bundle patch: the shared core of each base-backed profile, applied as\n# ONE insert over the empty profile root. Later bundle patches and the user's\n# profile cordis.patch.yml address these rows by id, with the last write\n# winning per row.\n#\n# A patch replaces the targeted row's whole `config` rather than merging into\n# it, so a row whose value differs by mode does NOT live here: it belongs to\n# each mode bundle, keeping any single row down to one bundle layer plus the\n# user's. Mode-specific rows appear below only with shared plugin identity and\n# neutral defaults; each mode bundle restates its complete configuration.\n#\n# Row order carries no load semantics (activation is service-availability\n# driven); the grouping is for readers.\n\n- insert:\n    - id: tool-plugin-manager\n      name: '@deepseek-ai/dsh-plugin-manager/tools'\n      disabled: true\n\n    - id: plugin-manager\n      name: '@deepseek-ai/dsh-plugin-manager'\n      disabled: !!js \"!ctx.get('profileContext')\"\n\n    - id: timer\n      name: '@deepseek-ai/cordis-plugin-timer'\n\n    # Profile configuration reloads by default; module roots are opt-in.\n    - id: hmr\n      name: '@deepseek-ai/dsh-hmr'\n      disabled: !!js \"!ctx.get('profileContext')\"\n      config:\n        root: []\n\n    - id: llm\n      name: '@deepseek-ai/dsh-llm'\n\n    - id: deepseek-llm-api-extensions\n      name: '@deepseek-ai/dsh-deepseek-llm-api-extensions'\n\n    - id: session\n      name: '@deepseek-ai/dsh-session'\n\n    - id: session-log-deepseek\n      name: '@deepseek-ai/dsh-session-log-deepseek'\n\n    - id: typert\n      name: '@deepseek-ai/dsh-typert-registry'\n\n    - id: typert-loader\n      name: '@deepseek-ai/dsh-typert-loader'\n\n    - id: typert-gateway\n      name: '@deepseek-ai/dsh-api-gateway'\n\n    # Method-level access control for non-owner Peers; the Gateway requires it,\n    # and its Client half publishes the standard access Hooks.\n    - id: remote-access\n      name: '@deepseek-ai/dsh-api-remote-access'\n\n    - id: session-title\n      name: '@deepseek-ai/dsh-session-title'\n      config:\n        fallbackMaxWords: 5\n        fallbackMaxBytes: 40\n        maxTitleBytes: 80\n\n    - id: session-title-llm\n      name: '@deepseek-ai/dsh-session-title-first-prompt-llm'\n      config:\n        targetWords: 5\n        targetCjkCharacters: 10\n        maxInputBytes: 4096\n        # A ceiling against runaway output, not a length target: the prompt\n        # keeps titles short, while reasoning a model cannot switch off also\n        # counts as output. Stays within common model output limits.\n        maxOutputTokens: 4096\n        timeoutMs: 60000\n\n    - id: user-questions\n      name: '@deepseek-ai/dsh-user-questions'\n\n    - id: agent\n      name: '@deepseek-ai/dsh-agent'\n\n    - id: plugin-package-inventory-deepseek\n      name: '@deepseek-ai/dsh-plugin-package-inventory-deepseek'\n\n    # The transport-independent default for Agents created by entry points.\n    # Settings may supply a saved selection; consumers read it at creation time.\n    - id: agent-default-model\n      name: '@deepseek-ai/dsh-agent-default-model'\n      config:\n        provider: deepseek-official\n        model: deepseek-flash\n\n    - id: jobs\n      name: '@deepseek-ai/dsh-jobs-local'\n\n    - id: llm-retry\n      name: '@deepseek-ai/dsh-llm-retry'\n\n    # Live Config forms persist through the active profile patch.\n\n    # Live configuration forms persist through the launcher's profile.\n    - id: config-editor\n      name: '@deepseek-ai/dsh-config-editor'\n      disabled: !!js \"!ctx.get('profileContext')\"\n\n    - id: settings\n      name: '@deepseek-ai/dsh-settings'\n      disabled: !!js \"!ctx.get('profileContext')\"\n\n    # Credential sources: managed `$DSH_HOME/.credentials.yaml`, then inherited\n    # environment, project `.env`, and user `.env` fallbacks.\n    # Adapters resolve references per request; the Models page writes only the\n    # managed document, which is never materialized into the process environment.\n    - id: authorization\n      name: '@deepseek-ai/dsh-authorization'\n\n    - id: deepseek-account\n      name: '@deepseek-ai/dsh-deepseek-account-platform'\n      config:\n        desktopPlatform: !!js \"ctx.get('profileContext')?.name === 'desktop' && ['darwin', 'win32'].includes(process.platform) ? process.platform : null\"\n\n    - id: credentials\n      name: '@deepseek-ai/dsh-credentials-local'\n\n    # The pi-ai multi-provider twin, mounted dormant: zero routes (and no extra\n    # models in the picker) until a `llm-pi-ai:` settings section supplies provider\n    # profiles — then those routes register live, keys resolving per request\n    # through their apiKeyEnv references, and drop again when the section empties.\n    # Supplying those profiles is exactly what the web Models page does. Which\n    # adapters exist is composition; which providers run is the user's settings\n    # document.\n    - id: llm-pi-ai\n      name: '@deepseek-ai/dsh-llm-pi-ai'\n\n    - id: session-persistence-jsonl\n      name: '@deepseek-ai/dsh-session-persistence-jsonl'\n      config:\n        root: !!js dshHomePath('sessions')\n\n    # Durable image bytes live outside the append-only session log. Messages\n    # keep content-addressed references that this shared backend resolves for\n    # provider requests and authorized history reads.\n    - id: attachment-local\n      name: '@deepseek-ai/dsh-attachment-local'\n\n    # Full-text session search is opt-in. `openAt: never` keeps\n    # ctx.sessionQuery mounted — exact reads, titles, and lineage traces\n    # (session export, subagent-fork Workspace inheritance) stay available —\n    # while search calls fail with SESSION_QUERY_SEARCH_DISABLED and SQLite is\n    # never opened; the Web sidebar search matches titles and workspace names\n    # only. Deployments enabling content search override `openAt` to\n    # `first-search` or `startup` in a later patch layer (profile\n    # cordis.patch.yml or a --patch overlay), typically with a durable `path`.\n    - id: session-query-sqlite\n      name: '@deepseek-ai/dsh-session-query-sqlite'\n      config:\n        path: ':memory:'\n        openAt: never\n\n    # Shared projection registry: subagent catalog identity (mode/label) folds\n    # through its registered units, so the `list_agents` surface below fails\n    # loud without it; web layers reuse this same mount for list rows.\n    - id: working-directory\n      name: '@deepseek-ai/dsh-working-directory'\n\n    - id: tool-working-directory\n      name: '@deepseek-ai/dsh-tool-working-directory'\n\n    - id: session-projection\n      name: '@deepseek-ai/dsh-session-projection'\n\n    # Durable KV storage: the storage hub, the json backend, and the\n    # schema-validated domain form over them. Session-layer persistence (the\n    # projection cache below; workspace in web layers)\n    # routes through this stack, so it belongs to the shared base.\n    - id: storage\n      name: '@deepseek-ai/dsh-storage'\n\n    - id: storage-json\n      name: '@deepseek-ai/dsh-storage-json'\n      config:\n        root: !!js dshHomePath('storages')\n\n    - id: storage-domain\n      name: '@deepseek-ai/dsh-storage-domain'\n      config:\n        backend: json\n\n    # Persisted projection cache: throttled write-behind over the\n    # session_projcache domain (per-record layout — one version-stamped\n    # checkpoint document per session), serving the session listing's\n    # projection column.\n    - id: session-projection-cache\n      name: '@deepseek-ai/dsh-session-projection-cache'\n      config:\n        writeEveryEvents: 200\n        writeIntervalMs: 5000\n\n    - id: otel\n      name: '@deepseek-ai/dsh-otel'\n\n    # OTel releases a Session-log prefix only after explicit user feedback,\n    # regardless of model provider. Ordinary activity never triggers capture.\n    # DSH_TELEMETRY_OTLP_URL overrides the production endpoint. A non-empty\n    # DSH_TELEMETRY_DISABLED — any value, including '0'/'false' — opts the\n    # process out (the launchers patch the row disabled; config cannot disable\n    # a row). Exports carry the harness home's anonymous user id ($DSH_HOME/.anonymous-user-id,\n    # random UUID; delete the file to reset the identity) as the Resource's\n    # user.id. Byte-bounded batching may turn an authorized prefix into\n    # several HTTP requests. Requests run serially; each has its own 1s\n    # transport timeout and 1.5s watchdog. A watchdog does not release the\n    # active request slot. The outer 3s shutdown deadline stops queued sends;\n    # large prefixes or an unsettled transport may leave records unsent.\n    # Every CLI exit path drains by disposing the root on SIGINT/SIGTERM.\n    - id: session-telemetry-otel\n      name: '@deepseek-ai/dsh-session-telemetry-otel'\n      config:\n        mode: !!js process.env.DSH_TELEMETRY_MODE || 'FEEDBACK_ONLY'\n        shutdownTimeoutMillis: 3000\n        maxRequestBytes: 4000000\n        exporter:\n          url: !!js process.env.DSH_TELEMETRY_OTLP_URL ?? 'https://dsh-otel-collector.deepseeksvc.com/v1/logs'\n          compression: gzip\n          timeoutMillis: 1000\n        processor:\n          scheduledDelayMillis: 10000\n          maxQueueSize: 2048\n          maxExportBatchSize: 2048\n          exportTimeoutMillis: 1500\n\n    - id: subprocess\n      name: '@deepseek-ai/dsh-subprocess-local'\n\n    # Every shipped CLI mode starts with the same file-effect boundary.\n    # The environment remains an explicit deployment override; otherwise fresh\n    # sessions pin workspace-write + ask through the permission service below.\n    - id: sandbox\n      name: '@deepseek-ai/dsh-sandbox-local'\n\n    - id: sandbox-policy\n      name: '@deepseek-ai/dsh-sandbox-policy'\n      config:\n        mode: !!js process.env.DSH_PERMISSION_MODE ?? 'workspace-write'\n        workspaceRoot: !!js process.cwd()\n\n    - id: bash-sandbox\n      name: '@deepseek-ai/dsh-bash-sandbox'\n      disabled: !!js process.platform === 'win32'\n      config:\n        timeoutMs: 60000\n\n    - id: pwsh-sandbox\n      name: '@deepseek-ai/dsh-pwsh-sandbox'\n      disabled: !!js process.platform !== 'win32'\n\n    - id: approval\n      name: '@deepseek-ai/dsh-user-approval'\n      config:\n        policy: !!js \"(process.env.DSH_PERMISSION_MODE ?? 'workspace-write') === 'danger-full-access' ? 'never' : 'ask'\"\n\n    - id: permission\n      name: '@deepseek-ai/dsh-permission-presets'\n      config:\n        presets:\n          read-only:\n            sandbox: read-only\n            approval: ask\n          workspace-write:\n            sandbox: workspace-write\n            approval: ask\n          danger-full-access:\n            sandbox: danger-full-access\n            approval: never\n\n    - id: shell-env\n      name: '@deepseek-ai/dsh-shell-env'\n\n    - id: tool-bash\n      name: '@deepseek-ai/dsh-tool-bash'\n      disabled: !!js process.platform === 'win32'\n\n    - id: tool-pwsh\n      name: '@deepseek-ai/dsh-tool-pwsh'\n      disabled: !!js process.platform !== 'win32'\n\n    - id: tool-jobs\n      name: '@deepseek-ai/dsh-tool-jobs'\n\n    - id: fs-observation-policy\n      name: '@deepseek-ai/dsh-fs-observation-policy'\n      disabled: true\n\n    - id: tool-fs\n      name: '@deepseek-ai/dsh-tool-fs'\n      config:\n        # Set false to drop the apply_patch tool beside edit.\n        applyPatch: false\n\n    - id: tool-fs-search\n      name: '@deepseek-ai/dsh-tool-fs-search'\n      config:\n        sampleOverCapGlobResults: false\n\n    - id: agent-instructions\n      name: '@deepseek-ai/dsh-agent-instructions'\n      config:\n        maxBytes: 65536\n\n    - id: skill\n      name: '@deepseek-ai/dsh-skill'\n\n    - id: skill-filesystem\n      name: '@deepseek-ai/dsh-skill-filesystem'\n\n    - id: tool-skill\n      name: '@deepseek-ai/dsh-tool-skill'\n\n    - id: commands\n      name: '@deepseek-ai/dsh-commands'\n\n    - id: command-feedback\n      name: '@deepseek-ai/dsh-command-feedback'\n\n    - id: goal\n      name: '@deepseek-ai/dsh-goal'\n\n    - id: goal-round-driver\n      name: '@deepseek-ai/dsh-goal-round-driver'\n\n    - id: command-goal\n      name: '@deepseek-ai/dsh-command-goal'\n\n    - id: plan-mode\n      name: '@deepseek-ai/dsh-plan-mode'\n      config:\n        section: |\n              You are in plan mode. Stay in plan mode until the user approves your plan through exit_plan_mode or switches the session mode. Imperative language to implement changes means plan the implementation, not execute it. A user's conversational agreement — including an answer confirming something you asked — approves nothing and does not end plan mode; fold the confirmed decision into the plan and submit it through exit_plan_mode.\n\n              Explore first. Use non-mutating reads, searches, static analysis, and checks to ground the plan in the actual repository. Do not edit or write files, change configuration, run formatters or code generation that rewrites tracked files, commit, or otherwise carry out the plan. Prefer existing functions and patterns over new machinery.\n\n              The tool catalog stays the same across modes for request-cache stability. These plan-mode rules override any later tool description or guidance that suggests using mutation tools; those tools remain listed only to keep the request shape stable. Do not use todo_write to track this planning phase: it tracks implementation after an approved plan, while the plan itself belongs in exit_plan_mode.\n\n              Resolve discoverable facts by inspection. Use ask_user_question only for user-owned choices or material ambiguity that inspection cannot answer. Do not ask the user where code lives or how current behavior works when you can find out.\n\n              Make the plan decision-complete: state the goal and success criteria; group implementation changes by subsystem; identify public API, schema, and data-flow changes; cover edge cases, failure modes, tests, acceptance criteria, and explicit assumptions. Keep it concise enough to review but detailed enough that another engineer can implement it without making design decisions.\n\n              When ready, call exit_plan_mode with the complete plan markdown, starting with a # title. Make exit_plan_mode the only and final tool call in that assistant response: it presents the plan for approval, and implementation begins only in a later step after approval. Do not paste the final plan as a plain reply or ask \"should I proceed?\" through prose or ask_user_question. If review rejects it, incorporate the feedback and present again. If the review channel is unavailable or aborted, stay in plan mode and ask the user to switch modes manually; do not proceed with implementation.\n\n    - id: token-meter\n      name: '@deepseek-ai/dsh-token-meter'\n\n    - id: compaction-basic\n      name: '@deepseek-ai/dsh-compaction-basic'\n\n    # Human `/compact`: one useful reduction below the automatic threshold. Backend\n    # independent, so it follows whichever compaction service this leaf mounts.\n    - id: command-compact\n      name: '@deepseek-ai/dsh-command-compact'\n\n    - id: subagent\n      name: '@deepseek-ai/dsh-subagent'\n\n    - id: agent-team\n      name: '@deepseek-ai/dsh-agent-team'\n      config:\n        maxTasks: 256\n\n    - id: tool-agent-team\n      name: '@deepseek-ai/dsh-tool-agent-team'\n\n    - id: subagent-spawn-in-process\n      name: '@deepseek-ai/dsh-subagent-spawn-in-process'\n      config:\n        providerName: spawn\n\n    - id: subagent-fork-in-process\n      name: '@deepseek-ai/dsh-subagent-fork-in-process'\n      config:\n        providerName: fork\n\n    # Continuable background children are selected per delegation tool. The\n    # separately loaded follow-up tool registers the one global `send_message`.\n    - id: tool-subagent-control\n      name: '@deepseek-ai/dsh-tool-subagent-control'\n\n    - id: tool-subagent\n      name: '@deepseek-ai/dsh-tool-subagent'\n      config:\n        provider: spawn\n        toolName: subagent\n\n    # Fork omits model-selection arguments for KV Cache reuse. Parent and child\n    # share the messaging tools; return guidance follows the inherited history.\n    # See packages/subagent/tool-subagent/README.md\n    # and .agents/notes/implemented/architecture/2026-08-10-fork-children-stay-one-shot.md.\n    - id: tool-subagent-fork\n      name: '@deepseek-ai/dsh-tool-subagent'\n      config:\n        provider: fork\n        toolName: subagent_fork\n\n    - id: ptc-runtime\n      name: '@deepseek-ai/dsh-ptc-runtime-node'\n\n    - id: workflow-ptc\n      name: '@deepseek-ai/dsh-workflow-ptc'\n      config:\n        provider: spawn\n\n    - id: tool-workflow\n      name: '@deepseek-ai/dsh-tool-workflow'\n\n    - id: timeout-policy\n      name: '@deepseek-ai/dsh-tool-call-timeout-policy'\n\n    - id: spill-local\n      name: '@deepseek-ai/dsh-spill-local'\n\n    - id: spill-policy\n      name: '@deepseek-ai/dsh-spill-policy'\n      config:\n        maxInlineTokens: 12500\n\n    # Durability checkpoints before each model request and top-level dispatch.\n    - id: session-checkpoint-policy\n      name: '@deepseek-ai/dsh-session-checkpoint-policy'\n\n    # Compacts oversized tool results before the broader conversation compactor\n    # runs, preserving the model-visible result within the configured budget.\n    - id: tool-result-pruner\n      name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n      config:\n        thresholdChars: 8192\n        headChars: 4096\n        tailChars: 1024\n\n    # When an image-capable route rejects a request as over its image budget,\n    # replace the oldest images with placeholders on the surface and retry.\n    - id: image-offload\n      name: '@deepseek-ai/dsh-compaction-image-offload'\n\n    - id: tool-todo\n      name: '@deepseek-ai/dsh-tool-todo'\n      config:\n        allowParallelInProgress: true\n\n    # Persisted same-session goals reach the model and the slash menu here; the\n    # domain, driver, and `/goal` command are above.\n    - id: tool-goal\n      name: '@deepseek-ai/dsh-tool-goal'\n\n    # Consecutive-repeat reminders on the tool chain.\n    - id: repeat-tool-reminder\n      name: '@deepseek-ai/dsh-repeat-tool-reminder'\n      config:\n        thresholds: [3, 5, 8]\n        argumentsPreviewChars: 500\n\n    # The shared base enables the stable model-facing web_search and web_fetch\n    # tools. The Web app disables this host row and composes both tools per agent\n    # preset; products with a stricter network policy override tool-web. Search\n    # defaults to the DeepSeek Search API (deepseek-search-api) and fetch to the\n    # anonymous local fetcher (http). The DeepSeek Search and Fetch APIs\n    # (deepseek-search-api, deepseek-fetch-api) follow the conversation: on the\n    # deepseek-account route they send the account token to that route's\n    # origin, and otherwise the API key of the DeepSeek API-key route to its\n    # origin, so a DEEPSEEK_API_KEY alone serves both without a sign-in.\n    # searchBaseURL / searchApiKeyEnv (fetch* for Fetch) pin one capability to\n    # its own endpoint and key instead.\n    # Legacy Messages search (deepseek-official) is selectable separately and\n    # uses its own endpoint, with the account token or DEEPSEEK_API_KEY.\n    # Anonymous fetch accepts only public\n    # HTTP(S) destinations, resolves and validates every destination, and pins\n    # every actual connection. This composition gives web_search 60s whichever\n    # provider serves it; the provider-neutral tool default remains 30s. The Web\n    # search provider and Web fetch provider\n    # menus on the Web search and fetch settings page select a provider for each\n    # capability in place of these defaults.\n    - id: web\n      name: '@deepseek-ai/dsh-web'\n      config:\n        searchProvider: deepseek-search-api\n        fetchProvider: http\n\n    - id: web-search-deepseek\n      name: '@deepseek-ai/dsh-web-search-deepseek'\n      config:\n        apiKeyEnv: DEEPSEEK_API_KEY\n\n    - id: web-deepseek-api\n      name: '@deepseek-ai/dsh-web-deepseek-api'\n\n    - id: web-fetch-http\n      name: '@deepseek-ai/dsh-web-fetch-http'\n\n    - id: tool-web\n      name: '@deepseek-ai/dsh-tool-web'\n      config:\n        fetch: true\n        searchTimeoutMs: 60000\n\n    - id: mcp-resources\n      name: '@deepseek-ai/dsh-mcp-resources'\n\n    # ── rows every mode mounts, whose values each overlay may state ──────────────\n\n    # Shared tool definitions and the deployment’s native executor.\n    - id: tools\n      name: '@deepseek-ai/dsh-tools'\n\n    - id: tool-executor-native\n      name: '@deepseek-ai/dsh-tool-executor-native'\n\n    - id: tool-executor-ptc\n      name: '@deepseek-ai/dsh-tool-executor-ptc'\n      disabled: true\n\n    # The deployment persona is a deployment choice; plan-mode and tool plugins own\n    # their own prompt sections.\n    - id: system-prompt\n      name: '@deepseek-ai/dsh-system-prompt'\n      config:\n        personaPrefix: ''\n\n    # Agents created at startup. The base stays empty; raw overlays may create\n    # agents, while Web creates sessions on client request.\n    - id: agent-loop\n      name: '@deepseek-ai/dsh-agent-loop'\n      config:\n        agents: []\n\n    # The sandboxed filesystem provider. `cwd` defaults to `process.cwd()`; an\n    # overlay can pin another workspace.\n    - id: fs-sandbox\n      name: '@deepseek-ai/dsh-fs-sandbox'\n\n    # The native DeepSeek adapter. No key or endpoint is inlined: both resolve per\n    # request from the `llm-deepseek:` settings section over this entry, with the\n    # key coming from the credential store below. Thinking defaults are a deployment\n    # choice.\n    - id: llm-deepseek\n      name: '@deepseek-ai/dsh-llm-deepseek-api-key'\n\n    - id: llm-deepseek-account\n      name: '@deepseek-ai/dsh-llm-deepseek-account'\n"
    },
    {
      "path": "packages/core/agent-loop/src/agent.ts",
      "content": "/**\n * Default Agent driver over queued turns and step-boundary input. Every request\n * is derived from the session log.\n * @module dsh-agent-loop/agent\n */\n\nimport type {\n  Agent,\n  AgentCancelCause,\n  AgentEventDispatch,\n  AgentOptions,\n  AgentStatus,\n  CancelOptions,\n  ModelSelection,\n  ModelSelectionProjectionState,\n  InboxTarget,\n  InboxState,\n  PreStepDecision,\n  RequestErrorAction,\n} from '@deepseek-ai/dsh-agent'\nimport { AgentModel, agentEvents, assembleContextFor } from '@deepseek-ai/dsh-agent'\nimport type { GenerateOptions, LlmCallConfig, Message, PreparedLlmCall } from '@deepseek-ai/dsh-llm'\nimport {\n  LlmError,\n  createAssistantMessage,\n  createDeveloperMessage,\n  errorChain,\n  markAgentLoopRequest,\n} from '@deepseek-ai/dsh-llm'\nimport { assertNever, deepFreeze } from '@deepseek-ai/dsh-util-values'\nimport type { Scope } from '@deepseek-ai/dsh-scope'\nimport { createScope } from '@deepseek-ai/dsh-scope'\nimport type { EpochHeader, RequestContext, Session, SessionId, SessionSeq, TurnEndReason, UserMessage } from '@deepseek-ai/dsh-session'\nimport { canonicalHeader, headerEquals, ToolCallRecovery } from '@deepseek-ai/dsh-session'\nimport { joinContextSections, renderContextSections, renderPrompt } from '@deepseek-ai/dsh-system-prompt'\nimport type { PromptAssembly } from '@deepseek-ai/dsh-system-prompt'\nimport { ToolActivationError, ToolBatchExecutionError } from '@deepseek-ai/dsh-tools'\nimport type { ResolvedToolSet } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { ReactLoopInbox } from './inbox.ts'\nimport { RuntimeContextProjection } from './runtime-context.ts'\nimport { AssistantStreamAttempt } from './assistant-stream.ts'\nimport { SystemPromptProjection } from './runtime-context.ts'\n\n/** Projected facts consumed by this driver; registration stays with the factory. */\ninterface LoopProjections {\n  /** Current model selection, including pending changes. */\n  readonly modelSelection: () => ModelSelectionProjectionState\n  /** Current queued and claimed input. */\n  readonly inbox: () => InboxState\n}\n\ntype Phase =\n  | { kind: 'idle'; lastTurn: number }\n  | {\n    kind: 'maintenance'\n    abort: AbortController\n    lastTurn: number\n    wakeRequested: boolean\n  }\n  | { kind: 'running'; abort: AbortController; turn: number; step: number; wakeRequested: boolean }\n\ntype StepEndReason = Extract<TurnEndReason, { kind: 'completed' | 'max-tokens' }>\n\ntype PreparedStep =\n  | { kind: 'reject' }\n  | {\n    kind: 'enter'\n    messages: UserMessage[]\n    startsRequestSeries?: true\n    assembly: PromptAssembly\n    selection: Readonly<ModelSelection>\n    /** Admission shared by the step's declarations and dispatch; the turn disposes it after the step. */\n    toolSet: ResolvedToolSet\n  }\n\n/** Remove adapter-derived values before plugins propose the next request config. */\nfunction requestProposal(header: EpochHeader): LlmCallConfig {\n  if (header.adapterDefaults === undefined) return header.config\n  const proposal = { ...header.config }\n  if (header.adapterDefaults.reasoningEffort === true) delete proposal.reasoningEffort\n  if (header.adapterDefaults.maxTokens === true) delete proposal.maxTokens\n  return proposal\n}\n\n/**\n * Read the cause `cancel()` passed when aborting a loop-owned signal, copying\n * only the fields `turn/end` records. The live reason stays the caller's\n * object, and Node's fetch assigns a `stack` onto it that `Session.append`\n * would either log or reject as data JSON cannot hold.\n * @param signal - a turn or maintenance signal this loop owns.\n * @returns the copied cause, or undefined while the signal is still live.\n */\nfunction abortedCancelCause(signal: AbortSignal): AgentCancelCause | undefined {\n  if (!signal.aborted) return undefined\n  // `cancel()` is the only aborter of the signals this loop owns.\n  const cause = signal.reason as AgentCancelCause\n  switch (cause.kind) {\n    case 'user':\n    case 'parent':\n    case 'disposed':\n      return { kind: cause.kind }\n    case 'hook':\n      return { kind: 'hook', reason: cause.reason }\n    /* v8 ignore next -- cancel accepts the closed AgentCancelCause union */\n    default:\n      return assertNever(cause)\n  }\n}\n\n/** Drives one session through turn and step boundaries. */\nexport class ReactLoopAgent implements Agent {\n  readonly model: AgentModel\n  readonly inbox: ReactLoopInbox\n  private phase: Phase\n  private activityDone: Promise<void> = Promise.resolve()\n\n  /** The agent-scoped registration boundary; the lifecycle owner unwinds it after the driver exits. */\n  readonly scope: Scope\n  readonly ctx: Context\n\n  /** Fused dispatcher, built once in the constructor so hot-path dispatches never allocate. */\n  private readonly dispatch: AgentEventDispatch\n\n  /** Whether this loop instance has appended its initial/resume request anchor. */\n  private requestHeaderLogged = false\n  /** Surface generation at attachment or the preceding built request. */\n  private requestSurfaceGeneration: number\n  private readonly runtimeContext: RuntimeContextProjection\n  /** Process-local revision of assistant frames for this attached Session. */\n  private assistantStreamRevision = 0\n  private assistantAttemptCounter = 0\n  private readonly systemPrompt: SystemPromptProjection\n  /** Identities fully frozen by this loop; weak references do not retain replaced history. */\n  private readonly frozenMessages = new WeakSet<Message>()\n\n  constructor(\n    private loopCtx: Context,\n    public readonly id: SessionId,\n    public readonly options: AgentOptions,\n    public readonly session: Session,\n    projections: LoopProjections,\n    lastTurn: number,\n  ) {\n    this.requestSurfaceGeneration = session.surface.contentGeneration\n    this.dispatch = agentEvents(loopCtx, this)\n    this.scope = createScope(loopCtx, this)\n    this.ctx = this.scope.ctx\n    this.model = new AgentModel(projections.modelSelection, session, options)\n    this.inbox = new ReactLoopInbox(projections.inbox, session, this.dispatch)\n    this.phase = { kind: 'idle', lastTurn }\n    this.runtimeContext = new RuntimeContextProjection(this.ctx, session)\n    this.systemPrompt = new SystemPromptProjection(session)\n  }\n\n  get status(): AgentStatus {\n    return this.phase.kind === 'idle' || this.phase.kind === 'maintenance' ? 'idle' : 'running'\n  }\n\n  /** Commit a phase and publish its externally visible status transition. */\n  private setPhase(next: Phase): void {\n    const previousStatus = this.status\n    this.phase = next\n    const status = this.status\n    if (status !== previousStatus) {\n      this.dispatch.emit('agent/status', { status })\n    }\n  }\n\n  send(message: UserMessage, target: InboxTarget, wakeup: boolean): void {\n    // Waking input cannot join an aborted activity, so it starts the next turn.\n    // Captured before the insertion so a reentrant cancel from a splice observer cannot reclassify it.\n    const wakingAfterAbort = wakeup && this.phase.kind !== 'idle' && this.phase.abort.signal.aborted\n    const resolvedTarget = wakingAfterAbort ? 'next-turn' : target\n    this.inbox.splice(resolvedTarget, Infinity, 0, [message])\n    if (wakeup) this.wakeDriver(wakingAfterAbort)\n  }\n\n  followup(input: UserMessage): void {\n    this.send(input, 'next-turn', true)\n  }\n\n  steer(input: UserMessage): void {\n    this.send(input, 'next-step', true)\n  }\n\n  inject(input: UserMessage): void {\n    this.send(input, 'next-step', false)\n  }\n\n  cancel(cause: AgentCancelCause, options: CancelOptions = {}): void {\n    if (!options.keepInbox) {\n      this.inbox.clear()\n      if (this.phase.kind !== 'idle') this.phase.wakeRequested = false\n    }\n    if (this.phase.kind !== 'idle') this.phase.abort.abort(cause)\n  }\n\n  runMaintenance<T>(job: (signal: AbortSignal) => Promise<T>): Promise<T> {\n    if (this.phase.kind !== 'idle') throw new Error(`agent \"${this.id}\" already has active work`)\n    const done = Promise.withResolvers<void>()\n    const maintenance: Phase = {\n      kind: 'maintenance',\n      abort: new AbortController(),\n      lastTurn: this.phase.lastTurn,\n      wakeRequested: false,\n    }\n    this.setPhase(maintenance)\n    this.activityDone = done.promise\n    return (async () => {\n      try {\n        return await job(maintenance.abort.signal)\n      } finally {\n        this.setPhase({ kind: 'idle', lastTurn: maintenance.lastTurn })\n        const cause = abortedCancelCause(maintenance.abort.signal)\n        if (cause?.kind !== 'disposed' && maintenance.wakeRequested && this.inbox.hasPending) this.wakeDriver()\n        done.resolve()\n      }\n    })()\n  }\n\n  /**\n   * Start one driver, or latch its wake behind maintenance or an aborted\n   * activity. A wake sent while idle always opens its turn boundary, even\n   * when its message was cleared; only a latched replay is suppressed when\n   * the queue no longer holds the wake.\n   * @param wakeAfterAbort - the {@link send} classification, captured before\n   *   the inbox insertion so a reentrant cancel cannot reclassify it.\n   */\n  private wakeDriver(wakeAfterAbort = false): void {\n    if (this.phase.kind !== 'idle') {\n      // Maintenance and aborted drivers cannot deliver the wake: latch it for\n      // replay at convergence. Live drivers claim queued work themselves;\n      // disposal never latches, so teardown waits on no model turn.\n      const reason = abortedCancelCause(this.phase.abort.signal)\n      if (reason?.kind !== 'disposed' && (this.phase.kind === 'maintenance' || wakeAfterAbort)) {\n        this.phase.wakeRequested = true\n      }\n      return\n    }\n    const driver = Promise.withResolvers<void>()\n    this.activityDone = driver.promise\n    this.setPhase({\n      kind: 'running',\n      abort: new AbortController(),\n      turn: this.phase.lastTurn,\n      step: 0,\n      wakeRequested: false,\n    })\n    this.loopCtx.agents.withInitiator(this, () => this.kick()).then(driver.resolve, driver.reject)\n  }\n\n  async whenIdle(): Promise<void> {\n    let activity: Promise<void>\n    do {\n      await (activity = this.activityDone)\n    } while (activity !== this.activityDone)\n  }\n\n  /** Report one failure at its live boundary, then preserve it for driver containment. */\n  private throwError(error: unknown): never {\n    const turn = this.phase.kind === 'running' ? this.phase.turn : this.phase.lastTurn\n    const step = this.phase.kind === 'running' ? this.phase.step : 0\n    this.dispatch.emit('agent/error', { turn, step, error })\n    throw error\n  }\n\n  private async kick(): Promise<void> {\n    try {\n      while (await this.turn()) {}\n    } catch (_error) {\n      // Reported failures and cancellation are contained at the driver boundary.\n    } finally {\n      /* v8 ignore next -- kick owns a running phase until this driver boundary */\n      if (this.phase.kind === 'running') {\n        const { turn, wakeRequested } = this.phase\n        this.setPhase({ kind: 'idle', lastTurn: turn })\n        if (wakeRequested && this.inbox.hasPending) this.wakeDriver()\n      }\n    }\n  }\n\n  private async preStep(target: InboxTarget, position: { turn: number; step: number }): Promise<PreparedStep> {\n    /* v8 ignore next -- private callers establish the running phase before proposing a step */\n    if (this.phase.kind !== 'running') throw new Error(`agent \"${this.id}\": pre-step outside running phase`)\n    const signal = this.phase.abort.signal\n    const claimed = this.inbox.claim(target, position.turn)\n    const selection = this.model.current()\n    if (selection === undefined) {\n      throw new Error(`agent \"${this.id}\" has no provider/model: set AgentOptions.provider and AgentOptions.model or record a model selection`)\n    }\n    const toolSet = await this.loopCtx.tools.resolve({ agent: this, modelSelection: selection, signal })\n    try {\n      const assembly = await this.loopCtx.systemPrompt.assemble({ ...assembleContextFor(this, signal), modelSelection: selection, toolSet })\n      signal.throwIfAborted()\n      const decision = await this.dispatch.waterfall(\n        'agent/pre-step', { messages: claimed, ...position, signal, modelSelection: selection },\n        (): Promise<PreStepDecision> => {\n          const sections = renderContextSections(assembly)\n          const context = this.runtimeContext.project(joinContextSections(sections), sections)\n          return Promise.resolve<PreStepDecision>({\n            kind: 'enter',\n            messages: context === undefined ? claimed : [...claimed, context],\n          })\n        },\n      )\n      signal.throwIfAborted()\n      if (decision.kind === 'reject') {\n        toolSet.dispose()\n        return decision\n      }\n      return { ...decision, assembly, selection, toolSet }\n    } catch (error: unknown) {\n      toolSet.dispose()\n      throw error\n    }\n  }\n\n  /** Whether the assembled tool schemas differ from the logged request header's. */\n  private toolsChanged(tools: PromptAssembly['tools']): boolean {\n    const baseline = this.session.requestHeader()\n    if (baseline === undefined) return false\n    return !headerEquals(baseline, canonicalHeader({ ...baseline, tools: [...tools] }))\n  }\n\n  /** Open one turn before claiming its first proposed step. */\n  private async turn(): Promise<boolean> {\n    if (this.phase.kind !== 'running') {\n      this.throwError(new Error(`agent \"${this.id}\": turn without driver reservation`))\n    }\n    const phase = this.phase\n    const { signal } = phase.abort\n    signal.throwIfAborted()\n    const turn = phase.turn + 1\n    try {\n      this.session.append('turn/start', { turn })\n    } catch (error: unknown) {\n      this.throwError(error)\n    }\n    phase.turn = turn\n    let turnEnds: TurnEndReason | null = null\n    let target: InboxTarget = 'next-turn'\n    try {\n      while (true) {\n        signal.throwIfAborted()\n        const step = phase.step + 1\n        const decision = await this.preStep(target, { turn, step })\n        if (decision.kind === 'reject') {\n          turnEnds = { kind: 'blocked' }\n          return false\n        }\n        try {\n          if (turnEnds && decision.messages.length === 0) break\n          // A removed waking message or an enter decision rewritten to empty\n          // still owns the initial turn boundary, but it spends no model call.\n          if (phase.step === 0 && decision.messages.length === 0) {\n            turnEnds = { kind: 'completed' }\n            return false\n          }\n          signal.throwIfAborted()\n          this.session.append('step/start', { turn, step })\n          phase.step = step\n          const toolRecovery = new ToolCallRecovery()\n          const stopRecovery = this.ctx.on('session/event', (session, event) => {\n            if (session === this.session) toolRecovery.observe(event)\n          })\n          try {\n            // max-tokens is sticky: once any step hits the ceiling, later steps\n            // that complete normally must not downgrade the turn outcome.\n            const stepEnd = await this.step(decision)\n            // max-tokens stays sticky: a later completed step must not\n            // downgrade the turn outcome.\n            if (turnEnds === null || turnEnds.kind !== 'max-tokens') turnEnds = stepEnd\n          } catch (error: unknown) {\n            try {\n              for (const event of toolRecovery.results()) {\n                this.session.append('tool/result', event.data, {\n                  surfaceOp: 'append',\n                  ...event.sourceEventSeqs === undefined ? {} : { sourceEventSeqs: event.sourceEventSeqs },\n                })\n              }\n            } catch (recoveryError: unknown) {\n              throw new AggregateError([error, recoveryError], 'Step failed and its pending tool results could not be recorded', { cause: error })\n            }\n            throw error\n          } finally {\n            stopRecovery()\n            this.session.append('step/end', { turn, step })\n          }\n        } finally {\n          // Admission closes once the step's tool batch settles or no step opens.\n          decision.toolSet.dispose()\n        }\n        signal.throwIfAborted()\n        if (turnEnds && this.inbox.nextStep.length === 0) {\n          await this.dispatch.serial('agent/turn-stopping', { turn, signal })\n          signal.throwIfAborted()\n        }\n        if (turnEnds && this.inbox.nextStep.length === 0) break\n        target = 'next-step'\n      }\n    } catch (error: unknown) {\n      // A cause is present exactly while the signal is aborted.\n      const cause = abortedCancelCause(signal)\n      if (cause !== undefined) {\n        turnEnds = { kind: 'aborted', reason: cause }\n        throw error\n      }\n      // Every failure is structured: an `LlmError` keeps its facts, a tool\n      // activation failure keeps its code, and anything else flattens to\n      // `errorChain` text under the `UNKNOWN` code.\n      turnEnds = {\n        kind: 'error',\n        error: error instanceof LlmError\n          ? error.failure\n          : { message: errorChain(error), code: error instanceof ToolActivationError ? error.code : 'UNKNOWN' },\n      }\n      this.throwError(error)\n    } finally {\n      try {\n        // oxlint-disable-next-line typescript/no-non-null-assertion -- every exit assigns a turn ending\n        this.session.append('turn/end', { turn, reason: turnEnds! })\n      } catch (error: unknown) {\n        this.throwError(error)\n      }\n    }\n    if (!this.inbox.hasPending) return false\n    phase.abort = new AbortController()\n    // A fresh controller makes a latch set on the old one stale: the live driver claims the queue itself.\n    phase.wakeRequested = false\n    phase.step = 0\n    return true\n  }\n\n  private async step(decision: Extract<PreparedStep, { kind: 'enter' }>): Promise<StepEndReason | null> {\n    /* v8 ignore next -- private callers establish the running phase before executing a step */\n    if (this.phase.kind !== 'running') throw new Error(`agent \"${this.id}\": step outside running phase`)\n    const { turn, step, abort: { signal } } = this.phase\n    signal.throwIfAborted()\n\n    const { assembly } = decision\n    const renderedPrompt = renderPrompt(assembly)\n    let firstAttempt = true\n    while (true) {\n      const { config, preparedCall } = await this.prepareRequest(turn, step, decision.selection, signal)\n      const currentContext = this.loopCtx.systemPrompt.refreshContext(assembly, {\n        ...assembleContextFor(this, signal), modelSelection: decision.selection,\n      })\n      const sections = renderContextSections(currentContext)\n      const context = this.runtimeContext.project(joinContextSections(sections), sections)\n      signal.throwIfAborted()\n      const startsRequestSeries = firstAttempt && decision.startsRequestSeries === true\n      const commits = this.systemPrompt.project(renderedPrompt, {\n        inHistory: preparedCall?.systemPromptUpdate === 'in-history',\n        startsSeries: startsRequestSeries\n          || this.requestSurfaceGeneration !== this.session.surface.contentGeneration\n          || (preparedCall?.toolUpdate === undefined && this.toolsChanged(assembly.tools)),\n      })\n      for (const { message, intent } of commits) {\n        this.session.append('system/message', { turn, step, message }, intent)\n      }\n      let contextAdmitted = false\n      if (firstAttempt) {\n        for (const message of decision.messages) {\n          if (message.source.kind === 'runtime-context') {\n            if (context !== undefined && !contextAdmitted) {\n              this.session.append('user/message', context, { surfaceOp: 'append' })\n              contextAdmitted = true\n            }\n          } else {\n            this.session.append('user/message', message, { surfaceOp: 'append' })\n          }\n        }\n      }\n      if (context !== undefined && !contextAdmitted) {\n        this.session.append('user/message', context, { surfaceOp: 'append' })\n      }\n      firstAttempt = false\n      const request = this.buildRequest(config, preparedCall, assembly.tools, { turn, step }, startsRequestSeries, signal)\n      const live = new AssistantStreamAttempt(\n        this.session.id,\n        ++this.assistantAttemptCounter,\n        () => ++this.assistantStreamRevision,\n        turn,\n        step,\n        (frame) => { this.dispatch.emit('agent/assistant-stream', { frame }) },\n      )\n      let started = false\n      try {\n        const stream = preparedCall?.stream(request) ?? this.loopCtx.llm.stream(request)\n        signal.throwIfAborted()\n        live.start()\n        started = true\n        for await (const chunk of stream) {\n          signal.throwIfAborted()\n          live.push(chunk)\n        }\n        signal.throwIfAborted()\n      } catch (error: unknown) {\n        if (!started) throw error\n        try {\n          if (signal.aborted) {\n            const content = live.interruptedBlocks()\n            if (content.length > 0) {\n              live.settle('assistant/message', () => this.session.append('assistant/message', {\n                turn,\n                step,\n                message: createAssistantMessage({\n                  content,\n                  source: {\n                    provider: request.provider,\n                    model: request.model,\n                    ...live.replayState === undefined ? {} : { replayState: live.replayState },\n                  },\n                }),\n                interrupted: true,\n                ...live.usage === undefined ? {} : { usage: live.usage },\n                stream: live.stream,\n              }, { surfaceOp: 'append' }).seq)\n            } else {\n              live.settle(\n                'assistant/attempt',\n                () => this.session.append('assistant/attempt', { turn, step, stream: live.stream }).seq,\n              )\n            }\n          } else {\n            live.settle(\n              'assistant/attempt',\n              () => this.session.append('assistant/attempt', { turn, step, stream: live.stream }).seq,\n            )\n          }\n        } catch (settlementError: unknown) {\n          throw new AggregateError(\n            [error, settlementError],\n            'Assistant stream failed and its durable settlement was rejected',\n            { cause: error },\n          )\n        }\n        throw error\n      }\n      try {\n        const finish = live.finish\n        if (finish.kind === 'error' || finish.kind === 'aborted') {\n          live.settle(\n            'assistant/attempt',\n            () => this.session.append('assistant/attempt', { turn, step, stream: live.stream }).seq,\n          )\n          const action = await this.dispatch.waterfall(\n            'agent/request-error', {\n              turn,\n              step,\n              provider: request.provider,\n              failure: finish.failure,\n              retryPolicy: preparedCall?.retryPolicy,\n              signal,\n            },\n            () => Promise.resolve<RequestErrorAction>(undefined),\n          )\n          signal.throwIfAborted()\n          if (action?.kind !== 'retry') {\n            throw new LlmError(finish.failure.message, finish.failure.code, finish.failure)\n          }\n          continue\n        }\n\n        const message = createAssistantMessage({\n          content: live.blocks(),\n          source: {\n            provider: request.provider,\n            model: request.model,\n            ...live.replayState !== undefined ? { replayState: live.replayState } : {},\n          },\n        })\n        live.settle(\n          'assistant/message',\n          () => this.session.append('assistant/message', {\n            turn,\n            step,\n            message,\n            ...live.usage === undefined ? {} : { usage: live.usage },\n            stream: live.stream,\n          }, { surfaceOp: 'append' }).seq,\n        )\n        if (finish.kind === 'max-tokens') return { kind: 'max-tokens' }\n\n        const toolCalls = message.content.filter(block => block.type === 'tool-call')\n        if (toolCalls.length === 0) return { kind: 'completed' }\n        const maxParallelToolCalls = this.loopCtx.agentLoop.config.maxParallelToolCalls.get()\n        try {\n          const result = await this.loopCtx.tools.execute({\n            calls: toolCalls, signal, agent: this, log: { turn, step },\n            maxParallelToolCalls, toolSet: decision.toolSet,\n          })\n          for (const context of result.additionalContexts) {\n            this.inbox.splice('next-step', this.inbox.nextStep.length, 0, [context])\n          }\n          return result.concluded ? { kind: 'completed' } : null\n        } catch (error: unknown) {\n          if (!(error instanceof ToolBatchExecutionError)) throw error\n          for (const context of error.partial.additionalContexts) {\n            this.inbox.splice('next-step', this.inbox.nextStep.length, 0, [context])\n          }\n          throw error.cause\n        }\n      } catch (error: unknown) {\n        if (!live.ended) live.abandon()\n        throw error\n      }\n    }\n  }\n\n  /** Resolve request config for the step's selection and bind its adapter before admitting model-visible input. */\n  private async prepareRequest(\n    turn: number,\n    step: number,\n    selection: Readonly<ModelSelection>,\n    signal: AbortSignal,\n  ): Promise<{ config: LlmCallConfig; preparedCall?: PreparedLlmCall }> {\n    const { session } = this\n\n    // A loop instance seeds output controls from its options until it logs its\n    // own header; later steps re-resolve marked defaults.\n    const maxTokens = this.options.maxTokens\n    const persisted: Partial<LlmCallConfig> = this.requestHeaderLogged\n      // oxlint-disable-next-line typescript/no-non-null-assertion -- the instance logged the header it now folds\n      ? requestProposal(session.requestHeader()!)\n      : maxTokens === undefined ? {} : { maxTokens }\n    const { provider: _provider, model: _model, reasoningEffort: _effort, ...controls } = persisted\n    const seedConfig = deepFreeze(structuredClone({ ...controls, ...selection }))\n    const proposedConfig = await this.dispatch.waterfall(\n      'agent/request', { turn, step, signal },\n      () => Promise.resolve(seedConfig),\n    )\n    signal.throwIfAborted()\n    if (proposedConfig.provider !== selection.provider || proposedConfig.model !== selection.model) {\n      throw new Error(`agent \"${this.id}\": agent/request proposed \"${proposedConfig.provider}/${proposedConfig.model}\" after step preparation fixed \"${selection.provider}/${selection.model}\"; use agent.model.select() before step preparation`)\n    }\n    if (proposedConfig.reasoningEffort !== selection.reasoningEffort) {\n      throw new Error(`agent \"${this.id}\": agent/request proposed reasoning effort \"${proposedConfig.reasoningEffort ?? 'adapter default'}\" after step preparation fixed \"${selection.reasoningEffort ?? 'adapter default'}\"; use agent.model.select() before step preparation`)\n    }\n    let config: LlmCallConfig\n    let preparedCall: PreparedLlmCall | undefined\n    try {\n      preparedCall = await this.loopCtx.llm.prepareCall(proposedConfig, signal)\n      config = preparedCall.config\n    } catch (error: unknown) {\n      // Middleware may serve an unregistered route; terminal dispatch still requires an adapter.\n      if (!(error instanceof LlmError) || error.code !== 'NO_ADAPTER') throw error\n      config = proposedConfig\n    }\n    signal.throwIfAborted()\n    return { config, ...preparedCall === undefined ? {} : { preparedCall } }\n  }\n\n  /** Log the resolved envelope and derive a frozen request from the admitted surface. */\n  private buildRequest(\n    config: LlmCallConfig,\n    preparedCall: PreparedLlmCall | undefined,\n    tools: GenerateOptions['tools'] & object,\n    position: { turn: number; step: number },\n    startsRequestSeries: boolean,\n    signal: AbortSignal,\n  ): GenerateOptions {\n    const { session } = this\n    const surfaceGeneration = session.surface.contentGeneration\n    const header = canonicalHeader({\n      config,\n      ...preparedCall === undefined ? {} : { adapterDefaults: preparedCall.adapterDefaults },\n      ...tools.length > 0 ? { tools } : {},\n    })\n    const baseline = this.session.requestHeader()\n    const startsSeries = startsRequestSeries\n      || this.requestSurfaceGeneration !== surfaceGeneration\n    let headerSeq: SessionSeq | undefined\n    if (!this.requestHeaderLogged) {\n      // Compaction during the first resumed pre-step must still mark a new series.\n      headerSeq = this.session.append('request/header', {\n        header,\n        reason: baseline === undefined ? 'initial' : 'resume',\n        ...startsSeries ? { startsSeries: true } : {},\n      }).seq\n      this.requestHeaderLogged = true\n    } else if (baseline === undefined || !headerEquals(baseline, header)) {\n      headerSeq = this.session.append('request/header', {\n        header,\n        reason: 'change',\n        ...startsSeries ? { startsSeries: true } : {},\n      }).seq\n    } else if (startsSeries) {\n      this.session.append('request/header', { header, reason: 'series' })\n    }\n    if (baseline !== undefined && headerSeq !== undefined) {\n      const previousNames = new Set(baseline.tools?.map(tool => tool.name))\n      const currentNames = new Set(tools.map(tool => tool.name))\n      const additions = tools.filter(tool => !previousNames.has(tool.name))\n        .map(tool => ({ type: 'tool-addition' as const, toolName: tool.name }))\n      const removals = (baseline.tools ?? []).filter(tool => !currentNames.has(tool.name))\n        .map(tool => ({ type: 'tool-removal' as const, toolName: tool.name }))\n      if (additions.length > 0 || removals.length > 0) {\n        session.append('developer/message', {\n          ...position,\n          message: createDeveloperMessage({ source: { kind: 'tool-registry' }, content: [...additions, ...removals] }),\n          ...additions.length > 0 ? { headerSeq } : {},\n        }, { surfaceOp: 'append' })\n      }\n    }\n    this.requestSurfaceGeneration = surfaceGeneration\n\n    const contextWindow = preparedCall?.context?.contextWindow\n    const systemPromptUpdate = preparedCall?.systemPromptUpdate\n    const requestContext: RequestContext = {\n      provider: config.provider,\n      model: config.model,\n      ...contextWindow === undefined ? {} : { contextWindow },\n      ...systemPromptUpdate === undefined ? {} : { systemPromptUpdate },\n    }\n    const previousContext = session.requestContext()\n    if (previousContext?.provider !== requestContext.provider\n      || previousContext.model !== requestContext.model\n      || previousContext.contextWindow !== requestContext.contextWindow\n      || previousContext.systemPromptUpdate !== requestContext.systemPromptUpdate) {\n      session.append('request/context', requestContext)\n    }\n    signal.throwIfAborted()\n\n    // canonicalHeader is shallow; append logs a detached snapshot, not these local values.\n    deepFreeze(header)\n    const boundaryMessages = session.deriveMessages()\n    for (const message of boundaryMessages) {\n      if (this.frozenMessages.has(message)) continue\n      deepFreeze(message)\n      this.frozenMessages.add(message)\n    }\n    Object.freeze(boundaryMessages)\n    const request = markAgentLoopRequest(Object.freeze({\n      ...header.config,\n      messages: boundaryMessages,\n      toolHistory: session.toolHistory(),\n      ...header.tools !== undefined ? { tools: header.tools } : {},\n      sessionId: this.session.id,\n      signal,\n    }))\n    return request\n  }\n}\n"
