      "path": "packages/core/tools/src/pipeline.ts",
      "content": "/** Shared tool invocation policy, cancellation, and result settlement. @module */\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ScopeKey } from '@deepseek-ai/dsh-scope'\nimport { scopeTarget } from '@deepseek-ai/dsh-scope'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport { HarnessError } from '@deepseek-ai/dsh-llm'\nimport type { UserMessage } from '@deepseek-ai/dsh-session'\nimport type {} from '@deepseek-ai/dsh-user-approval'\nimport { assertNever, deepFreeze, snapshotJsonValue, type JsonValue } from '@deepseek-ai/dsh-util-values'\nimport { TOOL_ABORTED, TOOL_ABORTED_BEFORE_DISPATCH, ToolNotFoundError, ToolOutputError } from './contracts.ts'\nimport { validateJsonSchemaValue } from './json-schema.ts'\nimport type { ToolsService } from './index.ts'\nimport type { ResolvedToolSet, ToolDefinition, ToolExecutionInput, ToolExecutionMode, ToolExecution, ToolRunContext, ToolExecutionResult, ToolExecutionSuccess, ToolErrorInfo, ToolExecutionToken, PreToolDecision, PostToolDecision } from './contracts.ts'\n\n/** Executor-owned lookup and restrictions applied before extensible execution policy. */\nexport interface ToolExecutionSource {\n  /**\n   * Override registry lookup for executor-owned capabilities; omitted uses the\n   * retained registry's executable lookup, which applies the call's step admission.\n   */\n  get?(name: string, scope?: ScopeKey, toolSet?: ResolvedToolSet): ToolDefinition | undefined\n  /** Reject an otherwise visible invocation before policy; omitted permits it. */\n  reject?(name: string, nested: boolean): Error | undefined\n}\n\n/** Prepared invocation; immediate results carry their post-execute requirement. */\nexport type ScheduledToolPreparation =\n  | { kind: 'dispatch'; exec: ToolRunContext }\n  | ({ exec: ToolRunContext } & ScheduledToolDispatch)\n\n/** A `post-result` receives post-execute; a `final-result` bypasses it. */\nexport type ScheduledToolDispatch =\n  | { kind: 'post-result'; result: ToolExecutionResult }\n  | { kind: 'final-result'; result: ToolExecutionResult }\n\n/** Registry-owned live execution object; public pipeline views stay readonly. */\ntype MutableToolRunContext = Omit<ToolRunContext, 'signal'> & { signal: AbortSignal }\n\n/** Approval decision plus whether the approval channel reported cancellation. */\ninterface ToolAskResolution {\n  readonly decision: Extract<PreToolDecision, { kind: 'allow' | 'deny' }>\n  readonly approvalCancelled: boolean\n}\n\n/** Caller cancellation and dispatch state kept outside the around-wrapper view. */\ninterface ToolCancellationState {\n  readonly callerSignal: AbortSignal\n  bodyInvoked: boolean\n}\n\n/** One dispatch-scoped fused signal plus listener cleanup after the body settles. */\ninterface FusedToolSignal {\n  readonly signal: AbortSignal\n  dispose(): void\n}\n\n/**\n * Shared invocation stages for batch and program schedulers. Schedulers order\n * prepare and complete calls while dispatch may overlap. Use executeToolBatch\n * for complete calls, including a single-call batch.\n */\nexport class ToolExecutionPipeline {\n  private readonly tools: ToolsService\n\n  constructor(private readonly ctx: Context, private readonly source: ToolExecutionSource = {}) {\n    // Accepted calls retain their event subject while the service is withdrawn during shutdown.\n    this.tools = ctx.tools\n  }\n\n  private get(name: string, scope: ScopeKey | undefined, toolSet: ResolvedToolSet | undefined): ToolDefinition | undefined {\n    return this.source.get === undefined\n      ? this.tools.executable(name, scope, toolSet)\n      : this.source.get(name, scope, toolSet)\n  }\n\n  private resolveExecution(\n    name: string, scope: ScopeKey | undefined, nested: boolean, toolSet: ResolvedToolSet | undefined,\n  ): ToolDefinition | undefined {\n    const tool = this.get(name, scope, toolSet)\n    return tool !== undefined && this.source.reject?.(name, nested) === undefined ? tool : undefined\n  }\n\n  /** Context deferred by a running tool body, keyed by its scheduler-owned execution. */\n  private deferredContexts = new WeakMap<ToolRunContext, UserMessage[]>()\n\n  /** Executions whose tool body declared the current turn complete. */\n  private concludingExecutions = new WeakSet<ToolExecution>()\n\n  /** Original caller cancellation, kept outside the wrapper-mutable execution object. */\n  private cancellationStates = new WeakMap<ToolRunContext, ToolCancellationState>()\n\n  /** Definition-owned final content transform snapshotted before policy begins. */\n  private contentFinalizers = new WeakMap<ToolRunContext, ToolDefinition['finalizeContent']>()\n\n  /** Execution-prepared content installed before post-execute policy. */\n  private contentProjectors = new WeakMap<ToolRunContext, ToolDefinition['projectContent']>()\n\n  /**\n   * Classify a pending call through the caller's visible tool definition. Only\n   * an exact `true` is parallel; unknown, hidden, undeclared, invalid, or\n   * throwing classifiers are exclusive.\n   * @param exec - call name, parsed arguments, and optional agent scope.\n   * @returns the fail-closed scheduling mode.\n   */\n  executionMode(exec: ToolExecutionInput): ToolExecutionMode {\n    const tool = this.resolveExecution(exec.name, exec.agent, exec.parent !== undefined, exec.toolSet)\n    if (!tool?.isConcurrencySafe) return { kind: 'exclusive' }\n    try {\n      const concurrencySafe: unknown = tool.isConcurrencySafe(exec.arguments)\n      return concurrencySafe === true ? { kind: 'parallel' } : { kind: 'exclusive' }\n    } catch {\n      return { kind: 'exclusive' }\n    }\n  }\n\n  private createExecution(exec: ToolExecutionInput): ScheduledToolPreparation | { kind: 'ready'; exec: MutableToolRunContext } {\n    const deferredContexts: UserMessage[] = []\n    const token = createExecutionToken()\n    const callId = exec.callId\n    const rootCallId = exec.rootCallId ?? callId\n    const name = exec.name\n    const agent = exec.agent\n    const parent = exec.parent\n    const signal = exec.signal\n    // Executor refusals precede extensible policy; unknown tools retain dispatch-stage handling.\n    const visible = this.get(name, agent, exec.toolSet)\n    const rejection = visible === undefined ? undefined : this.source.reject?.(name, parent !== undefined)\n    const rejected = rejection !== undefined\n    const concludingExecutions = this.concludingExecutions\n    const base = {\n      token,\n      callId,\n      rootCallId,\n      name,\n      signal,\n      ...agent !== undefined ? { agent } : {},\n      ...exec.toolSet !== undefined ? { toolSet: exec.toolSet } : {},\n      ...parent !== undefined ? { parent } : {},\n      ...exec.schema !== undefined ? { schema: exec.schema } : {},\n      deferContext(context: UserMessage): void {\n        deferredContexts.push(context)\n      },\n      concludeTurn(this: ToolExecution): void {\n        concludingExecutions.add(this)\n      },\n    }\n    // Capture callbacks before argument getters run; rejected calls retain finalization only when aborted.\n    const capturedFinalizer = visible?.finalizeContent?.bind(visible)\n    const capturedProjector = visible?.projectContent?.bind(visible)\n    const finalizerFor = (): ToolDefinition['finalizeContent'] | undefined =>\n      rejected && !signal.aborted ? undefined : capturedFinalizer\n    try {\n      const detached = snapshotJsonValue(exec.arguments)\n      if (detached === undefined) {\n        throw new TypeError('tool execution arguments must be losslessly JSON-serializable')\n      }\n      const execution: MutableToolRunContext = { ...base, arguments: deepFreeze(detached) }\n      this.deferredContexts.set(execution, deferredContexts)\n      this.contentFinalizers.set(execution, finalizerFor())\n      if (!rejected) this.contentProjectors.set(execution, capturedProjector)\n      this.cancellationStates.set(execution, {\n        callerSignal: signal,\n        bodyInvoked: false,\n      })\n      if (rejected) {\n        // Cancellation takes precedence over an executor refusal.\n        if (signal.aborted) {\n          return { kind: 'final-result', exec: execution, result: toolAbortedBeforeDispatchResult() }\n        }\n        return {\n          kind: 'final-result',\n          exec: execution,\n          result: toolErrorResult(rejection),\n        }\n      }\n      return { kind: 'ready', exec: execution }\n    } catch (error: unknown) {\n      const execution: MutableToolRunContext = { ...base, arguments: undefined }\n      this.contentFinalizers.set(execution, finalizerFor())\n      return { kind: 'final-result', exec: execution, result: toolErrorResult(error) }\n    }\n  }\n\n  /**\n   * Snapshot input, assign its correlation token, and run ordered pre-execute\n   * policy and guards. Cancellation skips a body that has not started.\n   * @param input - the caller-supplied execution input.\n   * @returns the prepared execution plus the next scheduler stage.\n   */\n  async prepare(input: ToolExecutionInput): Promise<ScheduledToolPreparation> {\n    const created = this.createExecution(input)\n    if (created.kind !== 'ready') return created\n    const exec = created.exec\n    if (this.callerCancelled(exec)) {\n      return { kind: 'final-result', exec, result: toolAbortedBeforeDispatchResult() }\n    }\n    try {\n      const carrier = scopeTarget(this.tools, exec.agent)\n      const gate = await this.ctx.waterfall(\n        carrier, 'tools/pre-execute', exec,\n        () => Promise.resolve<PreToolDecision>({ kind: 'allow' }),\n      )\n      const askResolution = gate.kind === 'ask'\n        ? await this.serviceAsk(exec, gate)\n        : { decision: gate, approvalCancelled: false }\n      const { decision } = askResolution\n      if (this.callerCancelled(exec) && askResolution.approvalCancelled) {\n        return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }\n      }\n      if (decision.kind === 'cancel') {\n        return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }\n      }\n      const denialReason = decision.kind === 'allow' ? this.tools.checkGuards(exec) : decision.reason\n      const denialInfo = decision.kind === 'deny' ? decision.info : undefined\n      if (denialReason !== undefined) {\n        return {\n          kind: 'post-result',\n          exec,\n          result: this.materializeFinalResult({\n            content: [{ type: 'text', text: `Error: ${denialReason}` }],\n            isError: true,\n            error: { message: denialReason, ...denialInfo === undefined ? {} : { info: denialInfo } },\n          }),\n        }\n      }\n      if (this.callerCancelled(exec)) {\n        return { kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() }\n      }\n      return { kind: 'dispatch', exec }\n    } catch (error: unknown) {\n      return { kind: 'final-result', exec, result: toolErrorResult(error) }\n    }\n  }\n\n  /** Whether the original caller signal is currently aborted. */\n  private callerCancelled(exec: ToolRunContext): boolean {\n    const state = this.cancellationStates.get(exec)\n    /* v8 ignore next -- only registry-minted executions reach the staged scheduler methods */\n    if (state === undefined) throw new Error('tool registry scheduler invariant violated: missing cancellation state')\n    return state.callerSignal.aborted\n  }\n\n  /** Canonical cancellation outcome selected by whether the tool body started. */\n  private cancellationResult(exec: ToolRunContext, prior?: ToolExecutionResult): ToolExecutionResult {\n    const state = this.cancellationStates.get(exec)\n    /* v8 ignore next -- only registry-minted executions reach the staged scheduler methods */\n    if (state === undefined) throw new Error('tool registry scheduler invariant violated: missing cancellation state')\n    return state.bodyInvoked\n      ? toolAbortedResult(prior)\n      : toolAbortedBeforeDispatchResult(prior)\n  }\n\n  /**\n   * Dispatch the registered body with the original caller signal fused back\n   * into any around-wrapper replacement. Cancellation never abandons the body:\n   * a started promise reaches quiescence before its outcome becomes `ABORTED`.\n   */\n  private async dispatchToolBody(exec: MutableToolRunContext): Promise<ToolExecutionResult> {\n    const state = this.cancellationStates.get(exec)\n    /* v8 ignore next -- only registry-minted executions reach the staged scheduler methods */\n    if (state === undefined) throw new Error('tool registry scheduler invariant violated: missing cancellation state')\n    const wrapperSignal = exec.signal\n    const fused = fuseToolSignals(state.callerSignal, wrapperSignal)\n    const signal = fused.signal\n\n    if (isAborted(signal)) {\n      fused.dispose()\n      return toolAbortedBeforeDispatchResult()\n    }\n    exec.signal = signal\n    try {\n      const tool = this.resolveExecution(exec.name, exec.agent, exec.parent !== undefined, exec.toolSet)\n      if (!tool) throw new ToolNotFoundError(exec.name)\n      state.bodyInvoked = true\n      const returned = await tool.execute(exec.arguments, exec)\n      const result = this.createSuccessResult(exec, tool, returned)\n      return isAborted(signal)\n        ? toolAbortedResult(result)\n        : result\n    } catch (error: unknown) {\n      return toolErrorResult(error)\n    } finally {\n      fused.dispose()\n      exec.signal = wrapperSignal\n    }\n  }\n\n  /**\n   * Run around-dispatch and the tool body. Tool and unknown-tool failures still\n   * receive post-execute; pipeline failures are already final. Started bodies\n   * drain on cancellation before a successful outcome becomes `ABORTED`.\n   * @param exec - the execution returned by this pipeline's prepare stage.\n   * @returns whether the result still needs post-execute.\n   */\n  async dispatch(exec: ToolRunContext): Promise<ScheduledToolDispatch> {\n    try {\n      const mutableExec = exec as MutableToolRunContext\n      const carrier = scopeTarget(this.tools, exec.agent)\n      const result = await this.ctx.waterfall(\n        carrier, 'tools/execute', mutableExec,\n        () => this.dispatchToolBody(mutableExec),\n      )\n      const normalized = this.normalizeDispatchResult(exec, result)\n      const deferredContexts = this.deferredContexts.get(exec)\n      /* v8 ignore next -- dispatch only receives executions minted by this registry's prepare stage */\n      if (deferredContexts === undefined) throw new Error('tool registry scheduler invariant violated: unprepared execution')\n      const resultWithDeferredContexts: ToolExecutionResult = deferredContexts.length === 0\n        ? normalized\n        : this.markCanonical(exec, {\n          ...normalized,\n          additionalContexts: [\n            ...deferredContexts,\n            ...normalized.additionalContexts ?? [],\n          ],\n        })\n      return {\n        kind: 'post-result',\n        result: this.callerCancelled(exec) && !resultWithDeferredContexts.isError\n          ? this.cancellationResult(exec, resultWithDeferredContexts)\n          : resultWithDeferredContexts,\n      }\n    } catch (error: unknown) {\n      return { kind: 'final-result', result: toolErrorResult(error) }\n    }\n  }\n\n  /**\n   * Run post-execute when required, apply definition-owned content finalization,\n   * and publish the lossless, frozen result. Policy and finalization failures\n   * become error results. Cancellation replaces a successful outcome before\n   * final materialization; tool-owned errors remain intact.\n   * @param exec - the execution returned by this pipeline's prepare stage.\n   * @param outcome - the preparation or dispatch result awaiting completion.\n   * @returns the same materialized result delivered to final observers.\n   */\n  async complete(exec: ToolRunContext, outcome: ScheduledToolDispatch): Promise<ToolExecutionResult> {\n    switch (outcome.kind) {\n      case 'final-result':\n        return this.finish(exec, outcome.result)\n      case 'post-result':\n        break\n      /* v8 ignore next -- closed-union exhaustiveness guard */\n      default:\n        return assertNever(outcome, 'scheduled tool outcome')\n    }\n    const { result } = outcome\n    try {\n      const project = this.contentProjectors.get(exec)\n      this.contentProjectors.delete(exec)\n      const content = project?.(exec, result)\n      const projected = content === undefined\n        ? result\n        : this.markCanonical(exec, this.materializeFinalResult({ ...result, content }))\n      const postResult = await this.postExecute(exec, projected)\n      return this.finish(\n        exec,\n        this.callerCancelled(exec) && !postResult.isError\n          ? this.cancellationResult(exec, postResult)\n          : postResult,\n      )\n    } catch (error: unknown) {\n      return this.finish(exec, toolErrorResult(error))\n    }\n  }\n\n  /**\n   * Materialize the candidate, apply definition-owned content finalization,\n   * then materialize and notify the authoritative result.\n   * @param exec - the prepared execution.\n   * @param result - final result.\n   * @returns the materialized final result.\n   * @internal\n   */\n  private finish(exec: ToolRunContext, result: ToolExecutionResult): ToolExecutionResult {\n    let materializedResult: ToolExecutionResult\n    try {\n      materializedResult = this.materializeFinalResult(result)\n    } catch (error: unknown) {\n      materializedResult = this.materializeFinalResult(toolErrorResult(error))\n    }\n    let finalResult: ToolExecutionResult\n    try {\n      finalResult = this.materializeFinalResult(this.applyFinalContent(exec, materializedResult))\n    } catch (error: unknown) {\n      finalResult = this.materializeFinalResult(toolErrorResult(error))\n    }\n    this.notifyResult(exec, finalResult)\n    return finalResult\n  }\n\n  /** Apply the snapshotted tool-owned content transform without exposing other result fields. */\n  private applyFinalContent(exec: ToolRunContext, result: ToolExecutionResult): ToolExecutionResult {\n    const finalizeContent = this.contentFinalizers.get(exec)\n    if (finalizeContent === undefined) return result\n    const content = finalizeContent(exec, result)\n    return content === undefined ? result : { ...result, content }\n  }\n\n  /** Notify observers without exposing a mutation or error channel into the outcome. */\n  private notifyResult(exec: ToolExecution, result: ToolExecutionResult): void {\n    // Freeze the registry's live object before observers receive its readonly\n    // WeakMap-keyable view.\n    Object.freeze(exec)\n    const { name: toolName, callId } = exec\n    const reportFailure = (error: unknown): void => {\n      this.ctx.logger.warn(`tool \"${toolName}\" (${callId}): tools/result observer failed: ${toolErrorMessage(error)}`)\n    }\n    const callbacks = this.ctx.events.dispatch('emit', [\n      scopeTarget(this.tools, exec.agent), 'tools/result', exec, result,\n    ])\n    for (const callback of callbacks) {\n      try {\n        const returned: unknown = callback(exec, result)\n        void Promise.resolve(returned).catch(reportFailure)\n      } catch (error: unknown) {\n        reportFailure(error)\n      }\n    }\n  }\n\n  /**\n   * Resolve an `ask` decision to allow/deny through the approval seam. The\n   * seam is consumed opportunistically with `ctx.get('approval')` — a\n   * deployment that composes no ApprovalService keeps the historical degrade\n   * to deny, and an unmount mid-session degrades the same way on the next ask.\n   * An agent-less execution also degrades: without an agent there is no\n   * session to audit to and no UI to route to. Otherwise the outcome maps\n   * one-to-one — `allowed-once` proceeds; the three non-grants deny with\n   * distinct reasons so the model can tell a human \"no\" from an absent\n   * approval channel.\n   */\n  private async serviceAsk(\n    exec: ToolExecution,\n    ask: Extract<PreToolDecision, { kind: 'ask' }>,\n  ): Promise<ToolAskResolution> {\n    const approval = this.ctx.get('approval')\n    if (approval === undefined) {\n      return {\n        decision: { kind: 'deny', reason: ask.reason ?? `tool \"${exec.name}\" requires approval (not yet supported)` },\n        approvalCancelled: false,\n      }\n    }\n    if (exec.agent === undefined) {\n      return {\n        decision: { kind: 'deny', reason: `tool \"${exec.name}\" requires approval, but the call has no agent to route it through` },\n        approvalCancelled: false,\n      }\n    }\n    const outcome = await approval.request({\n      agent: exec.agent,\n      toolName: exec.name,\n      callId: exec.callId,\n      ...ask.reason !== undefined ? { reason: ask.reason } : {},\n      ...ask.displayReason !== undefined ? { displayReason: ask.displayReason } : {},\n      signal: exec.signal,\n    })\n    switch (outcome) {\n      case 'allowed-once': return { decision: { kind: 'allow' }, approvalCancelled: false }\n      case 'rejected': return {\n        decision: { kind: 'deny', reason: `the user rejected tool \"${exec.name}\"` },\n        approvalCancelled: false,\n      }\n      case 'cancelled': return {\n        decision: { kind: 'deny', reason: `approval for tool \"${exec.name}\" was cancelled` },\n        approvalCancelled: true,\n      }\n      case 'unavailable': return {\n        decision: { kind: 'deny', reason: `tool \"${exec.name}\" requires approval, but no approval channel is available` },\n        approvalCancelled: false,\n      }\n      default: return assertNever(outcome, 'ApprovalOutcome')\n    }\n  }\n\n  /**\n   * Run the `tools/post-execute` waterfall over a dispatched `result` and apply\n   * its {@link PostToolDecision}: `accept` keeps the call successful (replacing\n   * `content` when given), `block` turns it into an `isError` whose content is\n   * the corrective `feedback`. Either decision may attach `additionalContexts`,\n   * which are ferried on the returned result for the loop's active-batch FIFO.\n   * Context deferred by the tool body survives an accepted result but is\n   * discarded when the outer call is blocked; a block exposes only context the\n   * blocking decision explicitly supplied.\n   * Runs inside `execute`'s outer try/catch (a throwing listener → isError).\n   */\n  private async postExecute(exec: ToolExecution, result: ToolExecutionResult): Promise<ToolExecutionResult> {\n    const decision = await this.ctx.waterfall(\n      scopeTarget(this.tools, exec.agent), 'tools/post-execute', exec, result,\n      () => Promise.resolve<PostToolDecision>({ kind: 'accept' }),\n    )\n    const decisionContexts = decision.additionalContexts ?? []\n    if (decision.kind === 'block') {\n      const message = failureMessageFromContent(decision.feedback)\n      return this.markCanonical(exec, {\n        content: decision.feedback,\n        isError: true,\n        error: { message },\n        ...decisionContexts.length > 0 ? { additionalContexts: decisionContexts } : {},\n      })\n    }\n    if (Object.hasOwn(decision, 'content') && Object.hasOwn(decision, 'value')) {\n      throw new TypeError('tools/post-execute accept decision cannot replace both value and content')\n    }\n    const additionalContexts = [\n      ...result.additionalContexts ?? [],\n      ...decisionContexts,\n    ]\n    if (Object.hasOwn(decision, 'value')) {\n      if (result.isError) {\n        throw new TypeError('tools/post-execute cannot replace the value of a failed result')\n      }\n      const tool = this.resolveExecution(exec.name, exec.agent, exec.parent !== undefined, exec.toolSet)\n      if (tool === undefined) throw new ToolNotFoundError(exec.name)\n      const replaced = this.createSuccessResult(exec, tool, decision.value)\n      return this.markCanonical(exec, {\n        ...replaced,\n        ...additionalContexts.length > 0 ? { additionalContexts } : {},\n      })\n    }\n    return this.markCanonical(exec, {\n      ...result,\n      ...decision.content !== undefined ? { content: decision.content } : {},\n      ...additionalContexts.length > 0 ? { additionalContexts } : {},\n    })\n  }\n\n  /** Registry-normalized results and the exact dispatch that validated each value. */\n  private readonly canonicalResults = new WeakMap<object, ToolExecutionToken>()\n\n  /** Mark one registry-normalized result as canonical only for its owning dispatch. */\n  private markCanonical<T extends ToolExecutionResult>(exec: ToolExecution, result: T): T {\n    this.canonicalResults.set(result, exec.token)\n    return result\n  }\n\n  /** Snapshot, validate, render, and optionally project one successful body value. */\n  private createSuccessResult(exec: ToolExecution, tool: ToolDefinition, candidate: unknown): ToolExecutionSuccess {\n    const detached = snapshotToolValue(tool.name, candidate)\n    const violations = validateJsonSchemaValue(tool.output.schema, detached, 'value')\n    if (violations.length > 0) throw new ToolOutputError(tool.name, violations)\n    const value = deepFreeze(detached)\n    let rendered: ContentBlock[]\n    try {\n      rendered = tool.output.render(exec.arguments, value)\n    } catch (error: unknown) {\n      throw projectionError(tool.name, 'render', error)\n    }\n    const content = snapshotProjection(tool.name, 'render', rendered)\n    let meta: JsonValue | undefined\n    if (tool.output.presentationMeta !== undefined) {\n      let projected: JsonValue\n      try {\n        projected = tool.output.presentationMeta(exec.arguments, value)\n      } catch (error: unknown) {\n        throw projectionError(tool.name, 'presentationMeta', error)\n      }\n      meta = snapshotProjection(tool.name, 'presentationMeta', projected)\n    }\n    const concludesTurn = this.concludingExecutions.has(exec)\n    return this.markCanonical(exec, this.materializeFinalResult({\n      isError: false,\n      value,\n      content,\n      ...meta !== undefined ? { meta } : {},\n      ...concludesTurn ? { concludesTurn: true as const } : {},\n    }) as ToolExecutionSuccess)\n  }\n\n  /** Normalize an around-dispatch wrapper's authored result through the owning output contract. */\n  private normalizeDispatchResult(exec: ToolExecution, result: ToolExecutionResult): ToolExecutionResult {\n    if (this.canonicalResults.get(result) === exec.token) return result\n    if (result.isError) {\n      return this.markCanonical(exec, {\n        isError: true,\n        error: result.error,\n        content: result.content,\n        ...result.meta !== undefined ? { meta: result.meta } : {},\n        ...result.additionalContexts !== undefined ? { additionalContexts: result.additionalContexts } : {},\n      })\n    }\n    const tool = this.resolveExecution(exec.name, exec.agent, exec.parent !== undefined, exec.toolSet)\n    if (tool === undefined) throw new ToolNotFoundError(exec.name)\n    const normalized = this.createSuccessResult(exec, tool, result.value)\n    return this.markCanonical(exec, {\n      ...normalized,\n      ...result.additionalContexts !== undefined ? { additionalContexts: result.additionalContexts } : {},\n    })\n  }\n\n  /** Materialize the authoritative commit outcome once, immediately before `tools/result`. */\n  private materializeFinalResult(result: ToolExecutionResult): ToolExecutionResult {\n    const presentation = {\n      content: result.content,\n      ...result.meta !== undefined ? { meta: result.meta } : {},\n      ...result.additionalContexts !== undefined ? { additionalContexts: result.additionalContexts } : {},\n    }\n    if (result.isError) {\n      return materializePresentation({ isError: true as const, error: result.error, ...presentation })\n    }\n    const detached = materializePresentation({\n      isError: false as const,\n      ...presentation,\n      ...result.concludesTurn === true ? { concludesTurn: true as const } : {},\n    })\n    return deepFreeze({ ...detached, value: result.value })\n  }\n}\n\n/** Convert one projector exception into the canonical invalid-output failure. */\nfunction projectionError(toolName: string, projector: 'render' | 'presentationMeta', error: unknown): ToolOutputError {\n  return new ToolOutputError(toolName, [`output.${projector} failed: ${toolErrorMessage(error)}`])\n}\n\n/** Snapshot one projector result before later durable-result materialization. */\nfunction snapshotProjection<T>(toolName: string, projector: 'render' | 'presentationMeta', candidate: T): T {\n  try {\n    const detached = snapshotJsonValue(candidate)\n    if (detached === undefined) {\n      throw new ToolOutputError(toolName, [`output.${projector} returned non-lossless JSON`])\n    }\n    return detached\n  } catch (error: unknown) {\n    if (error instanceof ToolOutputError) throw error\n    throw projectionError(toolName, projector, error)\n  }\n}\n\n/** Snapshot one body or policy value into the canonical invalid-output failure class. */\nfunction snapshotToolValue(toolName: string, candidate: unknown): JsonValue {\n  try {\n    const detached = snapshotJsonValue(candidate)\n    if (detached === undefined) throw new ToolOutputError(toolName, ['value is not lossless JSON'])\n    return detached as JsonValue\n  } catch (error: unknown) {\n    if (error instanceof ToolOutputError) throw error\n    throw new ToolOutputError(toolName, [`value snapshot failed: ${toolErrorMessage(error)}`])\n  }\n}\n\n/**\n * Best-effort human-readable message from an arbitrary thrown value: Error\n * instances use `.message`; non-Error objects with a string `message`\n * property (e.g. `throw { message: 'denied' }`) use it too; everything else\n * is stringified.\n * @param error - thrown value from a tool or policy callback.\n * @returns a printable failure message, including for hostile thrown values.\n */\nexport function toolErrorMessage(error: unknown): string {\n  try {\n    if (error instanceof Error) return error.message\n    if (typeof error === 'object' && error !== null\n      && 'message' in error && typeof error.message === 'string') {\n      return error.message\n    }\n    return String(error)\n  } catch {\n    // A hostile thrown value can trap `instanceof`, property access, or string\n    // coercion. Error normalization is the outermost safety boundary, so its\n    // fallback must itself be total.\n    return '<unprintable thrown value>'\n  }\n}\n\n/** Derive one failure message from policy feedback without changing its rendered blocks. */\nfunction failureMessageFromContent(content: ContentBlock[]): string {\n  const text = content\n    .map(block => block.type === 'text' ? block.text : `[${block.type} content]`)\n    .join('\\n')\n  return text.length > 0 ? text : 'tool result blocked by post-execute policy'\n}\n\n/** Snapshot and freeze one durable tool-result projection or reject lossy data. */\nfunction materializePresentation<T>(candidate: T): T {\n  const detached = snapshotJsonValue(candidate)\n  if (detached === undefined) {\n    throw new TypeError('tool result must be losslessly JSON-serializable')\n  }\n  return deepFreeze(detached)\n}\n\n/** Structured `{ name, code }` for a thrown HarnessError, else undefined. */\nfunction errorInfo(error: unknown): ToolErrorInfo | undefined {\n  try {\n    return error instanceof HarnessError ? { name: error.name, code: error.code } : undefined\n  } catch {\n    return undefined\n  }\n}\n\n/** Mint a same-process correlation token whose identity is its value. */\nfunction createExecutionToken(): ToolExecutionToken {\n  return Symbol('dsh.tool.execution') as ToolExecutionToken\n}\n\nfunction toolErrorResult(error: unknown): ToolExecutionResult {\n  const info = errorInfo(error)\n  const message = toolErrorMessage(error)\n  return {\n    content: [{ type: 'text', text: `Error: ${message}` }],\n    isError: true,\n    error: { message, ...info ? { info } : {} },\n  }\n}\n\n/** Read live abort state across an await without treating it as synchronously immutable. */\nfunction isAborted(signal: AbortSignal): boolean {\n  return signal.aborted\n}\n\n/**\n * Fuse caller and wrapper cancellation without nesting `AbortSignal.any`.\n * Keeping the relay dispatch-scoped also removes listeners when work settles.\n */\nfunction fuseToolSignals(caller: AbortSignal, wrapper: AbortSignal): FusedToolSignal {\n  if (caller === wrapper) return { signal: caller, dispose() {} }\n\n  const controller = new AbortController()\n  let listening = false\n  const dispose = (): void => {\n    if (!listening) return\n    listening = false\n    caller.removeEventListener('abort', abortFromCaller)\n    wrapper.removeEventListener('abort', abortFromWrapper)\n  }\n  const abortFrom = (source: AbortSignal): void => {\n    const reason: unknown = source.reason\n    controller.abort(reason)\n    dispose()\n  }\n  const abortFromCaller = (): void => { abortFrom(caller) }\n  const abortFromWrapper = (): void => { abortFrom(wrapper) }\n\n  if (wrapper.aborted) abortFromWrapper()\n  else if (caller.aborted) abortFromCaller()\n  else {\n    listening = true\n    caller.addEventListener('abort', abortFromCaller, { once: true })\n    wrapper.addEventListener('abort', abortFromWrapper, { once: true })\n  }\n  return { signal: controller.signal, dispose }\n}\n\n/** Canonical result when cancellation supersedes success after body invocation. */\nfunction toolAbortedResult(prior?: ToolExecutionResult): ToolExecutionResult {\n  const additionalContexts = prior?.additionalContexts ?? []\n  return {\n    content: [{ type: 'text', text: 'Error: tool call aborted' }],\n    isError: true,\n    error: {\n      message: 'tool call aborted',\n      info: { name: 'AbortError', code: TOOL_ABORTED },\n    },\n    ...additionalContexts.length > 0 ? { additionalContexts } : {},\n  }\n}\n\n/** Canonical result when cancellation prevents tool body invocation. */\nfunction toolAbortedBeforeDispatchResult(prior?: ToolExecutionResult): ToolExecutionResult {\n  const additionalContexts = prior?.additionalContexts ?? []\n  return {\n    content: [{ type: 'text', text: 'Error: tool call aborted before dispatch' }],\n    isError: true,\n    error: {\n      message: 'tool call aborted before dispatch',\n      info: { name: 'AbortError', code: TOOL_ABORTED_BEFORE_DISPATCH },\n    },\n    ...additionalContexts.length > 0 ? { additionalContexts } : {},\n  }\n}\n\nexport { executeToolBatch } from './batch.ts'\n"
    },
    {
      "path": "packages/interaction/user-approval/src/index.ts",
      "content": "/**\n * Service Definition for the approval capability seam, covering requests, cancellation, audit, and per-session policy. Missing\n * answerers fail closed; grants apply only to the requested action.\n * @module @deepseek-ai/dsh-user-approval\n */\n\nimport { randomUUID } from 'node:crypto'\nimport { Context, Service } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { z as zod } from 'zod'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport { createUserMessage, type ToolCallId } from '@deepseek-ai/dsh-llm'\nimport type { ContextFormed } from '@deepseek-ai/dsh-llm'\ndeclare module '@deepseek-ai/dsh-llm' {\n  interface MessageSourceMap {\n    'user-approval': { kind: 'user-approval' } & ContextFormed\n  }\n}\n\nimport { scopeTarget } from '@deepseek-ai/dsh-scope'\nimport type { Session, SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { ProjectionDefinition, ProjectionHandle } from '@deepseek-ai/dsh-session-projection'\nimport type {} from '@deepseek-ai/dsh-system-prompt'\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    approval: ApprovalService\n  }\n}\n\ndeclare module '@deepseek-ai/dsh-session/types' {\n  interface SessionEventMap {\n    /**\n     * The session's approval policy was switched — log-only, durable,\n     * replayable, never in the model transcript (the model learns the policy\n     * from the runtime-context snapshot and live switch notices). The LAST\n     * such event is the session's override.\n     * `source: 'delegation'` marks an override seeded into a child; an absent\n     * source is a runtime switch.\n     */\n    'approval/policy': {\n      policy: ApprovalPolicy\n      /** Marks an override seeded into a child at delegation. */\n      source?: 'delegation'\n    }\n  }\n}\n\nimport { ApprovalRequestId } from './types.ts'\nimport type { ApprovalOutcome, ApprovalRequestEvent } from './types.ts'\n\nexport { ApprovalRequestId } from './types.ts'\nexport type { ApprovalOutcome } from './types.ts'\n\n/** Every {@link ApprovalOutcome}, for runtime normalization of answerer returns. */\nconst OUTCOMES: readonly ApprovalOutcome[] = ['allowed-once', 'rejected', 'cancelled', 'unavailable']\n\n/**\n * A session's approval policy — what happens to an {@link ApprovalService}\n * ask BEFORE any interactive answerer sees it:\n *\n * - `'ask'` (the default) — delegate to the composed answerers; with none\n *   composed the chain falls through to the fail-closed `'unavailable'`.\n * - `'never'` — never prompt anyone: every ask resolves `'rejected'`\n *   deterministically. The strict headless stance (CI, unattended runs) and\n *   the policy whose outcome is knowable without asking.\n */\nexport type ApprovalPolicy = 'ask' | 'never'\n\n/** Every {@link ApprovalPolicy}, for option advertisement and runtime validation of untrusted policy strings. */\nexport const APPROVAL_POLICIES: readonly ApprovalPolicy[] = ['ask', 'never']\n\n/** Model-facing statement for the deterministic `'never'` policy. */\nconst NEVER_SENTENCE = 'Approval prompts are disabled in this session: actions that require approval are rejected automatically — do not request sandbox escalation (do not set `sandbox_permissions`).'\n/** Model-facing statement for an interactive policy that may still fail closed. */\nconst ASK_SENTENCE = 'Approval prompts are enabled in this session: operations that require approval may ask through the configured answerers; without an available answerer, the request fails closed.'\n/** Model-facing policy names in switch notices; a bare `never` reads as \"approval is never granted\". */\nconst POLICY_NOTICE_NAMES: Readonly<Record<ApprovalPolicy, string>> = {\n  ask: 'ask the user for approval',\n  never: 'never ask the user for approval',\n}\n\ninterface ApprovalState {\n  policy: ApprovalPolicy | null\n  // Mirrors AgentRegistry's turn enclosure without requiring an agent registry.\n  turnOpen: boolean\n}\n\nconst approvalStateDefinition = {\n  key: 'approvalState',\n  stateVersion: 1,\n  stateSchema: zod.object({\n    policy: zod.enum(['ask', 'never']).nullable(),\n    turnOpen: zod.boolean(),\n  }),\n  init: (): ApprovalState => ({ policy: null, turnOpen: false }),\n  apply(state: ApprovalState, event: SessionEvent): ApprovalState {\n    switch (event.type) {\n      case 'approval/policy':\n        return state.policy === event.data.policy ? state : { ...state, policy: event.data.policy }\n      case 'turn/start':\n        return state.turnOpen ? state : { ...state, turnOpen: true }\n      case 'turn/end':\n        return state.turnOpen ? { ...state, turnOpen: false } : state\n      default:\n        return state\n    }\n  },\n} satisfies ProjectionDefinition<'approvalState', ApprovalState>\n\n/**\n * Append the sole durable representation of a session policy override. Invalid\n * values throw before the log changes; projected state follows the committed record.\n * @param session - the session the override belongs to.\n * @param policy - the policy in effect until the next switch.\n */\nexport function setApprovalPolicy(session: Session, policy: ApprovalPolicy): void {\n  if (!APPROVAL_POLICIES.includes(policy)) {\n    throw new TypeError('approval policy must be one of \"ask\" or \"never\"')\n  }\n  session.append('approval/policy', { policy })\n}\n\n/**\n * Readonly same-process permission question. `callId` links to an already\n * presented tool call, so arguments are not duplicated here.\n */\nexport interface ApprovalRequest extends ApprovalRequestEvent {\n  /**\n   * The agent on whose behalf the question is asked. Routes the question (a\n   * UI answerer only answers for agents it owns) and receives the audit\n   * events on its session log.\n   */\n  readonly agent: Agent\n  /** The tool the question is about (presentation and audit). */\n  readonly toolName: string\n  /**\n   * The exact tool call being decided, when the asker has one — lets a UI\n   * attach the prompt to the tool call it already streamed.\n   */\n  readonly callId?: ToolCallId\n  /** The asker's human-readable explanation of WHY it is asking. */\n  readonly reason?: string\n  /**\n   * Aborting withdraws the question: the request settles `'cancelled'`\n   * immediately and a late answer from a still-pending answerer is discarded.\n   */\n  readonly signal?: AbortSignal\n}\n\n/** Plugin config. All optional — `static Config` supplies the defaults. */\nexport interface Config {\n  /**\n   * The deployment's default {@link ApprovalPolicy} for sessions without an\n   * `approval/policy` override — `'ask'` delegates to the composed answerers\n   * (fail-closed with none); `'never'` auto-rejects every ask without\n   * prompting (the deterministic CI/unattended stance).\n   */\n  readonly policy?: ApprovalPolicy\n}\n\n/**\n * Approval service that applies session policy before answerers and logs every\n * ask/outcome pair to the requesting session. It exposes deterministic policy\n * changes to the model through the runtime-context snapshot and switch notices.\n */\nexport class ApprovalService extends Service {\n  static inject = ['sessionProjections']\n\n  static Config: z<Config> = z.object({\n    policy: z.union(['ask', 'never'] as const).default('ask'),\n  })\n\n  private approvalProjectionHandle!: ProjectionHandle<ApprovalState>\n\n  constructor(ctx: Context, public config: Config) {\n    super(ctx, 'approval')\n  }\n\n  protected async [Service.init](): Promise<void> {\n    this.approvalProjectionHandle = await this.ctx.sessionProjections.register(approvalStateDefinition)\n    // Registration can finish after an unload has started. Do not add effects then.\n    if (this.ctx.fiber.uid === null) return\n\n    const effective = (agent: Agent): ApprovalPolicy => this.effectivePolicy(agent.session)\n\n    // The complete current value travels after retained history, so switching\n    // policy does not rewrite the stable system-prompt cache prefix.\n    await this.ctx.inject(['systemPrompt'], (scope: Context) => {\n      scope.systemPrompt.context({\n        name: 'approval:policy',\n        order: scope.systemPrompt.getContextOrder('APPROVAL_POLICY'),\n        text: (context) => {\n          const agent = context.agent\n          // A bare assemble() (tests, diagnostics) has no session to state.\n          if (agent === undefined) return ''\n          const policy = effective(agent)\n          return policy === 'never' ? NEVER_SENTENCE : ASK_SENTENCE\n        },\n      })\n    })\n  }\n\n  /**\n   * Switch one live agent's policy and queue the transition for its next model\n   * step. Session initialization uses {@link setApprovalPolicy} directly\n   * because there is no previously visible policy to change.\n   * @param agent - the live agent whose policy is changing.\n   * @param policy - the new effective policy.\n   */\n  setPolicy(agent: Agent, policy: ApprovalPolicy): void {\n    const previous = this.effectivePolicy(agent.session)\n    if (previous === policy) return\n    setApprovalPolicy(agent.session, policy)\n    agent.inject(createUserMessage({\n      content: [{\n        type: 'text',\n        text: `The user changed the approval policy from \"${POLICY_NOTICE_NAMES[previous]}\" to \"${POLICY_NOTICE_NAMES[policy]}\".`,\n      }],\n      source: { kind: 'user-approval' },\n    }))\n  }\n\n  /**\n   * Ask the composed answerers to decide one readonly same-process request.\n   * The service borrows the request, agent, session, and live signal directly.\n   * The request requires an open turn because the audit pair must be enclosed\n   * by the durable log's commit/replay boundary; an idle ask rejects before\n   * appending anything. The answerer phase always produces an outcome: an\n   * aborted signal yields `'cancelled'`, a missing or throwing answerer yields\n   * `'unavailable'` (fail closed), and a rogue non-vocabulary return value is\n   * normalized to `'unavailable'`. A failure that prevents either audit append\n   * from committing still rejects because returning an unlogged decision would\n   * violate the pair. Session contains post-commit observer failures, so an\n   * authoritative append cannot reject the request or suppress its matching\n   * audit event.\n   * @param req - the pending decision (agent, tool identity, reason, signal).\n   * @returns the closed outcome; `'allowed-once'` is the only grant.\n   * @throws when no turn is open or either audit event fails before the session\n   *   append commit point.\n   */\n  async request(req: ApprovalRequest): Promise<ApprovalOutcome> {\n    const session = req.agent.session\n    if (!this.approvalStateOf(session).turnOpen) {\n      throw new Error(\n        'approval.request() outside an open turn: the approval/asked + approval/decided audit pair '\n        + 'must be turn-enclosed (a bare event between turns is crash-tail garbage on reload). '\n        + 'Ask from inside the turn that needs the decision.',\n      )\n    }\n    const id = ApprovalRequestId(randomUUID())\n    session.append('approval/asked', {\n      id,\n      toolName: req.toolName,\n      ...req.callId !== undefined ? { callId: req.callId } : {},\n      ...req.reason !== undefined ? { reason: req.reason } : {},\n    })\n    const outcome = await this.decide(req, session)\n    session.append('approval/decided', { id, outcome })\n    return outcome\n  }\n\n  /**\n   * The session's effective policy: its projected override, else the\n   * configured default (the schema already defaulted an omitted policy to\n   * `'ask'`; the `??` only narrows the optional-input TYPE).\n   * @param session - the exact accepted session whose policy applies.\n   * @returns the policy every ask for this session resolves under right now.\n   */\n  private effectivePolicy(session: Session): ApprovalPolicy {\n    return this.overrideOf(session) ?? this.config.policy ?? 'ask'\n  }\n\n  /**\n   * Read the session override without applying the configured default.\n   * @param session - session whose log supplies the override.\n   * @returns the last logged policy, or `undefined` without one.\n   */\n  overrideOf(session: Session): ApprovalPolicy | undefined {\n    return this.approvalStateOf(session).policy ?? undefined\n  }\n\n  private approvalStateOf(session: Session): ApprovalState {\n    return this.approvalProjectionHandle.stateOf(session)\n  }\n\n  /**\n   * Dispatch the waterfall, contained and raced against the request signal.\n   * @param req - the borrowed public request.\n   * @param session - the request agent's session used for policy lookup.\n   * @returns the normalized closed outcome.\n   */\n  private async decide(req: ApprovalRequest, session: Session): Promise<ApprovalOutcome> {\n    const signal = req.signal\n    if (signal?.aborted) return 'cancelled'\n    // The 'never' policy is decided HERE, before any dispatch: a listener\n    // registered with `prepend: true` after this service mounts would sit\n    // ahead of any gate LISTENER, so a listener-shaped gate cannot keep the\n    // documented promise that 'never' rejects deterministically regardless\n    // of registration order — only the service's own request path can.\n    if (this.effectivePolicy(session) === 'never') return 'rejected'\n    // Enter the promise chain BEFORE dispatching: a listener that throws\n    // SYNCHRONOUSLY (before its first await) must land in the same rejection\n    // path as an async one — `Promise.resolve(call())` would let it escape\n    // the containment into the caller.\n    const answer: Promise<ApprovalOutcome> = Promise.resolve().then(\n      () => this.ctx.waterfall(\n        scopeTarget(req.agent, req.agent), 'approval/request', req,\n        () => Promise.resolve<ApprovalOutcome>('unavailable'),\n      ),\n    ).then(\n      // Normalize a rogue (non-vocabulary) answerer return to the fail-closed\n      // outcome instead of leaking it into callers' closed-union switches.\n      outcome => OUTCOMES.includes(outcome) ? outcome : 'unavailable',\n      // A throwing answerer must fail the QUESTION closed, not the caller's\n      // tool call open — the seam contains its callbacks.\n      () => 'unavailable',\n    )\n    if (signal === undefined) return answer\n    return await new Promise<ApprovalOutcome>((resolve) => {\n      const onAbort = () => {\n        signal.removeEventListener('abort', onAbort)\n        resolve('cancelled')\n      }\n      signal.addEventListener('abort', onAbort, { once: true })\n      void answer.then((outcome) => {\n        signal.removeEventListener('abort', onAbort)\n        // After an abort won the race this resolve is a settled-promise no-op:\n        // the late answer is discarded by construction.\n        resolve(outcome)\n      })\n    })\n  }\n}\n\nexport default ApprovalService\n"
    },
    {
      "path": "packages/session/session-checkpoint-policy/src/index.ts",
      "content": "/**\n * Semantic durability checkpoints for model requests, top-level tool dispatch,\n * and completed agent steps.\n * @module @deepseek-ai/dsh-session-checkpoint-policy\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Session } from '@deepseek-ai/dsh-session'\nimport type { StreamChunk } from '@deepseek-ai/dsh-llm'\nimport { TOOL_ABORTED_BEFORE_DISPATCH, type ToolExecutionResult } from '@deepseek-ai/dsh-tools'\nimport type { PreStepDecision } from '@deepseek-ai/dsh-agent'\nimport type {} from '@deepseek-ai/dsh-session-persistence'\n\n/** Cordis plugin name used by Loader diagnostics. */\nexport const name = 'session-checkpoint-policy'\n\n/** Services whose request, tool, session, and persistence boundaries this policy joins. */\nexport const inject = ['llm', 'sessionPersistence', 'sessions', 'tools']\n\n/**\n * Delay construction of the downstream model stream until the complete logged\n * request prefix is durable. A checkpoint rejection prevents adapter dispatch.\n *\n * @param ctx - plugin context that owns the session store.\n * @param session - live session named by the model request.\n * @param next - downstream `llm/stream` chain.\n * @returns a stream that checkpoints before requesting its first chunk.\n */\nfunction afterCheckpoint(\n  ctx: Context,\n  session: Session,\n  next: () => AsyncIterable<StreamChunk>,\n): AsyncIterable<StreamChunk> {\n  return (async function* (): AsyncIterable<StreamChunk> {\n    await ctx.sessions.flush(session)\n    yield* next()\n  })()\n}\n\n/** Materialize the canonical result for a call cancelled before tool dispatch. */\nfunction abortedBeforeDispatchResult(): ToolExecutionResult {\n  return {\n    content: [{ type: 'text', text: 'Error: tool call aborted before dispatch' }],\n    isError: true,\n    error: {\n      message: 'tool call aborted before dispatch',\n      info: { name: 'AbortError', code: TOOL_ABORTED_BEFORE_DISPATCH },\n    },\n  }\n}\n\n/**\n * Install semantic checkpoint listeners. Loop-built model calls checkpoint the\n * logged request before adapter dispatch; top-level tool calls checkpoint their\n * recorded call before the tool body; the next request boundary checkpoints\n * the preceding response/result batch. Nested tool dispatches reuse the durable outer call.\n *\n * Checkpoint failures are fail-closed at the model and tool side-effect\n * boundaries: the downstream adapter or tool body is not invoked.\n *\n * @param ctx - plugin context that owns the listeners.\n */\nexport function apply(ctx: Context): void {\n  ctx.on('llm/stream', (options, next): AsyncIterable<StreamChunk> => {\n    if (options.sessionId === undefined) return next()\n    const session = ctx.sessions.get(options.sessionId)\n    return session === undefined ? next() : afterCheckpoint(ctx, session, next)\n  })\n\n  ctx.on('tools/execute', async (exec, next): Promise<ToolExecutionResult> => {\n    if (exec.agent === undefined || exec.parent !== undefined) return next()\n    await ctx.sessions.flush(exec.agent.session)\n    if (exec.signal.aborted) return abortedBeforeDispatchResult()\n    return next()\n  })\n\n  // Before each request, persist everything committed by the preceding step;\n  // the first step's call is an intentional no-op beyond any prompt intake.\n  ctx.on('agent/pre-step', async ({ agent }, next): Promise<PreStepDecision> => {\n    await ctx.sessions.flush(agent.session)\n    return next()\n  })\n}\n"
    },
    {
      "path": "packages/session/session-persistence-jsonl/src/index.ts",
      "content": "/**\n * JSONL durable session-persistence backend. It stores a header and contiguous\n * events in immutable generation files under one directory per session and serves the handle-based\n * `SessionPersistence` API: `create`/`open` return per-session handles, and\n * every read validates the same fail-closed storage contract.\n * @module @deepseek-ai/dsh-session-persistence-jsonl\n */\n\nimport { Context, type Fiber } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport {\n  createSessionFormatCatalogWithChildren,\n  SessionFormatUnsupportedMigrationError,\n  sessionFormatCatalog,\n} from '@deepseek-ai/dsh-session-format-catalog'\nimport { readdirSync, type Dirent } from 'node:fs'\nimport { open, mkdir, readdir, realpath, link, rm, stat, truncate } from 'node:fs/promises'\nimport { dirname, join, resolve } from 'node:path'\nimport { performance } from 'node:perf_hooks'\nimport { scheduler } from 'node:timers/promises'\nimport { createHash, randomBytes } from 'node:crypto'\nimport pLimit, { type LimitFunction } from 'p-limit'\nimport {\n  SessionPersistence, SessionPersistenceRevision, SessionFormatUnsupportedError,\n  SessionPersistenceCorruptionError,\n  SessionAlreadyExistsError, SessionPersistenceNotFoundError,\n  assertStoredId, materializeCreateHeader, sessionFormatVersionRefusal, validateStoredEvents,\n  type SessionAccess, type SessionHandle,\n  type SessionHandleReadResult,\n  type SessionLocation, type SessionPersistenceCreateOptions,\n  type SessionPersistenceListOptions, type SessionPersistenceOpenOptions,\n  type SessionPersistenceSnapshot, type SessionPersistenceStatOptions,\n  type SessionPersistenceRevision as PersistenceRevision,\n} from '@deepseek-ai/dsh-session-persistence'\nimport { JsonlBackendTracker, JsonlSessionHandle, type StorageHandleState } from './storage.ts'\nimport { SessionWriteLease } from './lease.ts'\nimport { SESSION_FORMAT_VERSION, SessionId as makeSessionId, SessionLogOffset } from '@deepseek-ai/dsh-session'\nimport type { SessionEvent, SessionId, SessionHeader, SessionLogOffset as SessionLogOffsetType } from '@deepseek-ai/dsh-session'\nimport {\n  assertNoRetiredHeaderFields, encodeSegment, eventLines, generationLogFilename, generationLogPath, logPath, logSuffix,\n  parseGenerationLogFilename, projectDir, scanLog, sessionDir, SessionLogScanner, toHeaderLine,\n  type JsonlCompression,\n} from './format.ts'\nimport {\n  compressZstdFrame, createZstdFrameDecoder, decompressZstdFrame, decompressZstdPrefix, scanZstdFrames,\n} from './zstd.ts'\nimport { ensureDurableDirectoryWin32, publishNewFileWin32 } from './win32.ts'\nimport { verifyCurrentGenerationInWorker } from './migration-verifier.ts'\nimport { prepareCatalogFacts } from './catalog-migration.ts'\nimport {\n  JsonlGenerationSourceChangedError,\n  JsonlGenerationUnsupportedMigrationError,\n  prepareJsonlMigration,\n  readStableJsonlFile,\n  type JsonlGenerationFormatAdapter,\n  type JsonlPhysicalIdentity,\n  type PreparedJsonlMigration,\n} from './generation.ts'\n\nexport type { JsonlCompression } from './format.ts'\n\n/**\n * Internal handoff-reuse policy, not deployment configuration: a cold\n * observation and the resume that immediately follows it reuse one parsed\n * log, so the memo only needs the sessions in flight between those steps.\n */\nconst COLD_LOG_MEMO_MAX_ENTRIES = 2\n\nconst DEFAULT_COMPRESSION: JsonlCompression = 'zstd'\n/**\n * Internal scheduling constant, not deployment configuration: balance\n * frame-boundary event-loop yields against `setImmediate` overhead. One frame\n * remains an indivisible synchronous decode.\n */\nconst ZSTD_DECODE_YIELD_INTERVAL_MS = 500\n\n/** Assert that the independently decodable first frame contains only the header record. */\nfunction assertZstdHeaderFrame(plaintext: Buffer): void {\n  if (plaintext.length === 0 || plaintext.indexOf(0x0A) !== plaintext.length - 1) {\n    throw new Error('corrupt Zstandard session log: first frame is not exactly one header line')\n  }\n}\n\n/** Loader schema for the JSONL artifact's physical encoding. */\nexport const JsonlCompressionSchema: z<JsonlCompression> = z.union([\n  z.const('zstd'),\n  z.const('none'),\n]).default(DEFAULT_COMPRESSION)\n\n/** Default maximum listing filesystem operations in flight per backend. */\nconst DEFAULT_LIST_CONCURRENCY = 3\n\n/** Plugin config for the JSONL backend's root, physical encoding, and listing concurrency. */\nexport interface Config {\n  /**\n   * Root directory for all session files. Required (no default): a default of\n   * `process.cwd()` would scatter session files as the process's cwd changes\n   * (bash calls, subprocesses). Sessions group under human-readable project\n   * directories, then per-session directories. An existing root must be a\n   * readable directory; an absent root is created on first materialization.\n   */\n  root: string\n  /** Physical encoding; defaults to checksummed Zstandard frames. */\n  compression?: JsonlCompression\n  /**\n   * Maximum directory, header, and stat reads in flight across all concurrent\n   * listings of this backend (`list()`, the root encoding check, and historical\n   * fingerprints). Defaults to 3.\n   */\n  listConcurrency?: number\n}\n\n/** Logical header paired with the catalog's selected physical-generation classification. */\ninterface GenerationHeader {\n  readonly header: SessionHeader\n  readonly formatStatus: NonNullable<SessionPersistenceSnapshot['formatStatus']>\n}\n\n/** One stored event graph whose producer has established immutable sharing. */\ninterface FrozenStoredEvents extends SessionHandleReadResult {\n  readonly eventState: 'shared-frozen'\n}\n\n/** State shared by prepared historical and published current logs. */\ninterface StoredLogBase extends FrozenStoredEvents {\n  readonly meta: SessionHeader\n  readonly tornTruncateTo: number | undefined\n  /** Complete events recovered from the torn final frame; the write path rewrites them durably. */\n  readonly recoveredTail: SessionEvent[]\n  /** Exact fork-inherited prefix length stored in the header line. */\n  readonly inheritedEventCount: SessionLogOffsetType\n  readonly revision: PersistenceRevision\n}\n\n/** A decoded current generation that is already durable. */\ninterface CurrentStoredLog extends StoredLogBase {\n  readonly status: 'current'\n}\n\n/** A migrated historical generation retained until an explicit write open publishes it. */\ninterface PreparedStoredLog extends StoredLogBase {\n  readonly status: 'prepared'\n  readonly validateRelatedSources: () => Promise<void>\n  readonly publication: {\n    readonly source: ResolvedJsonlGeneration\n    readonly value: PreparedJsonlMigration\n  }\n}\n\n/** A validated logical log, either durable current state or prepared historical state. */\ntype StoredLog = CurrentStoredLog | PreparedStoredLog\n\n/** Deep-freeze acyclic stored JSON; its arrays contain only indexed JSON values. */\nfunction freezeStoredEvent(event: SessionEvent): void {\n  const pending: object[] = [event]\n  while (pending.length > 0) {\n    // The non-empty check proves an object remains to visit.\n    // oxlint-disable-next-line typescript/no-non-null-assertion\n    const current = pending.pop()!\n    Object.freeze(current)\n    if (Array.isArray(current)) {\n      for (let index = 0; index < current.length; index += 1) {\n        const child: unknown = current[index]\n        if (child !== null && typeof child === 'object') pending.push(child)\n      }\n    } else {\n      for (const key in current) {\n        const child = (current as Record<string, unknown>)[key]\n        if (child !== null && typeof child === 'object') pending.push(child)\n      }\n    }\n  }\n}\n\n/** Establish immutable sharing for one decoded event graph and report that state. */\nfunction freezeStoredEvents(events: SessionEvent[]): FrozenStoredEvents {\n  for (const event of events) freezeStoredEvent(event)\n  Object.freeze(events)\n  return { eventState: 'shared-frozen', events }\n}\n\n/** One authoritative immutable generation selected from a Session directory. */\ninterface ResolvedJsonlGeneration {\n  readonly sourcePath: string\n  readonly sourceVersion: number\n  readonly currentPath: string\n}\n\n/** One backend-owned historical preparation shared by its current callers. */\ninterface MigrationPreparation {\n  readonly sourcePath: string\n  readonly sourceRevision: PersistenceRevision\n  readonly controller: AbortController\n  readonly promise: Promise<PreparedStoredLog>\n  settled: boolean\n  waiters: number\n}\n\n/** Build the stat-derived best-effort change token shared by full and lightweight reads. */\nfunction fileRevision(identity: JsonlPhysicalIdentity): PersistenceRevision {\n  return SessionPersistenceRevision([\n    identity.dev,\n    identity.ino,\n    identity.size,\n    identity.mtimeNs,\n    identity.ctimeNs,\n  ].join(':'))\n}\n\n/** Whether a filesystem error means absence; every non-ENOENT failure must surface. */\nfunction isENOENT(error: unknown): boolean {\n  return (error as NodeJS.ErrnoException | null)?.code === 'ENOENT'\n}\n\n/**\n * Run `task` over `items` through the backend's shared listing limiter and\n * settle every call. Callers consume the outcomes in input order, so the first\n * failure they report matches a sequential loop whatever the completion order.\n * A limited task must never wait on the same limiter.\n * @param limit - the backend's shared listing limiter.\n * @param items - inputs in their sequential order.\n * @param task - per-item operation.\n * @returns one outcome per item, in input order.\n */\nfunction settleLimited<T, R>(\n  limit: LimitFunction,\n  items: readonly T[],\n  task: (item: T) => Promise<R>,\n): Promise<PromiseSettledResult<R>[]> {\n  return Promise.allSettled(items.map(item => limit(() => task(item))))\n}\n\n/**\n * Unwrap outcomes from {@link settleLimited}, rethrowing the first rejection in input order.\n * @param outcomes - outcomes in input order.\n * @returns the fulfilled values in input order.\n */\nfunction settledValues<R>(outcomes: readonly PromiseSettledResult<R>[]): R[] {\n  return outcomes.map((outcome) => {\n    if (outcome.status === 'rejected') throw outcome.reason\n    return outcome.value\n  })\n}\n\n/** Whether a filesystem-owned failure should retain its original errno and path. */\nfunction isErrnoException(error: unknown): error is NodeJS.ErrnoException {\n  return typeof (error as NodeJS.ErrnoException | null)?.code === 'string'\n}\n\n/** Preserve an Error abort reason and normalize hostile non-Error reasons. */\nfunction abortError(signal: AbortSignal): Error {\n  return signal.reason instanceof Error\n    ? signal.reason\n    : new Error('session migration preparation aborted', { cause: signal.reason })\n}\n\n/** Let one caller stop waiting without transferring cancellation ownership to shared work. */\nfunction waitWithAbort<T>(operation: Promise<T>, signal?: AbortSignal): Promise<T> {\n  if (signal === undefined) return operation\n  /* v8 ignore next -- requireStoredLog synchronously rechecks the signal immediately before waiting. */\n  if (signal.aborted) return Promise.reject(abortError(signal))\n  return new Promise<T>((resolve, reject) => {\n    const stopWaiting = (): void => {\n      reject(abortError(signal))\n    }\n    signal.addEventListener('abort', stopWaiting, { once: true })\n    void operation.then(\n      (value) => {\n        signal.removeEventListener('abort', stopWaiting)\n        resolve(value)\n      },\n      (error: unknown) => {\n        signal.removeEventListener('abort', stopWaiting)\n        /* v8 ignore else -- the preparation owner normalizes every rejection before this waiter sees it. */\n        if (error instanceof Error) {\n          reject(error)\n        } else {\n          reject(new Error('session migration preparation failed', { cause: error }))\n        }\n      },\n    )\n  })\n}\n\n/**\n * The JSONL backend registered as `ctx.sessionPersistence` by the plugin.\n * Sessions materialize lazily: a created session is\n * visible to this process immediately, reaches disk on its first append or\n * flush, and never existed if the process crashes before that.\n */\nclass JsonlSessionPersistence extends SessionPersistence {\n  /** Backend label for diagnostics and effects; shadows `Service.name` without changing the service key. */\n  override readonly name = 'session-persistence-jsonl'\n\n  private root: string\n  private compression: JsonlCompression\n  /**\n   * Bounds directory, header, and stat I/O across every concurrent listing of\n   * this backend (`list()`, the root encoding check, historical fingerprints).\n   * Queued tasks of a cancelled listing run and reject at their signal check.\n   */\n  private readonly listLimit: LimitFunction\n  private rootEncodingCheck: Promise<void> | undefined\n  private readonly generationFormat: Omit<JsonlGenerationFormatAdapter, 'createRestore'>\n  /**\n   * Bounded LRU of parsed, validated stored logs keyed by session id and\n   * guarded by the stat-derived revision, so an immediate cold-read handoff\n   * (observation then resume) parses the artifact once. Every local mutation\n   * for an id invalidates its entry; a foreign write misses through the\n   * revision guard.\n   */\n  private readonly coldLogMemo = new Map<SessionId, StoredLog>()\n  /** One joinable decode/migration operation per selected historical Session file revision. */\n  private readonly migrationPreparations = new Map<SessionId, MigrationPreparation>()\n\n  constructor(ctx: Context, public config: Config, private readonly tracker: JsonlBackendTracker) {\n    super(ctx)\n    /* v8 ignore next 5 -- generated catalog and Session source share one build-time version owner. */\n    if (sessionFormatCatalog.currentVersion !== SESSION_FORMAT_VERSION) {\n      throw new Error(\n        `session-persistence-jsonl: format catalog v${sessionFormatCatalog.currentVersion} `\n        + `does not match Session v${SESSION_FORMAT_VERSION}`,\n      )\n    }\n    // Resolve once so later process.cwd() changes cannot split one backend across roots.\n    this.root = resolve(config.root)\n    this.compression = config.compression ?? DEFAULT_COMPRESSION\n    this.listLimit = pLimit(config.listConcurrency ?? DEFAULT_LIST_CONCURRENCY)\n    this.generationFormat = {\n      currentVersion: sessionFormatCatalog.currentVersion,\n      encodeHeader: (header, inheritedEventCount) =>\n        sessionFormatCatalog.encodeCurrentHeader(header, inheritedEventCount),\n      encodeEvent: event => sessionFormatCatalog.encodeCurrentEvent(event),\n      isUnsupportedMigrationError: (error): error is SessionFormatUnsupportedMigrationError =>\n        error instanceof SessionFormatUnsupportedMigrationError,\n    }\n    this.assertUsableRoot()\n  }\n\n  /**\n   * Refusal-diagnostics hook: the absolute target path, without touching the filesystem.\n   * @param meta - the stored header naming the session and its cwd.\n   * @returns the artifact kind and absolute path.\n   */\n  private locate(meta: SessionHeader): SessionLocation {\n    return { kind: 'jsonl', path: logPath(this.root, meta.cwd, meta.id, this.compression) }\n  }\n\n  // --- SessionPersistence service API ---\n\n  /**\n   * Create a new stored session and take its write ownership. The session is\n   * visible to this process immediately; the physical artifact appears on the\n   * first append or flush.\n   * @param header - the immutable header to store; must be losslessly\n   *   JSON-serializable with a non-negative safe-integer `createdAt`.\n   * @param options - optional cancellation.\n   * @returns the owned write handle.\n   */\n  async create(header: SessionHeader, options?: SessionPersistenceCreateOptions): Promise<SessionHandle> {\n    options?.signal?.throwIfAborted()\n    const snapshot = materializeCreateHeader(header)\n    // Fail fast on a seeded/cut mismatch with the exact refusal the header\n    // line encoder enforces at materialization.\n    toHeaderLine(snapshot, options?.inheritedEventCount)\n    const inheritedEventCount = SessionLogOffset(options?.inheritedEventCount ?? 0)\n    await this.ensureRootEncoding()\n    options?.signal?.throwIfAborted()\n    if (this.tracker.hasPending(snapshot.id) || await this.findLog(snapshot.id, options?.signal) !== undefined) {\n      throw new SessionAlreadyExistsError(snapshot.id)\n    }\n    options?.signal?.throwIfAborted()\n    // No lock yet: before materialization there is no durable artifact for\n    // another process to contend over, so the handle acquires the lock right\n    // before its first log bytes publish (ensureLease); an unmaterialized\n    // session leaves no filesystem footprint at all.\n    this.tracker.registerCreated(snapshot, inheritedEventCount)\n    return this.tracker.adopt(new JsonlSessionHandle(this, snapshot.id, snapshot, 'write', { cursor: 0, materialized: false, inheritedEventCount }))\n  }\n\n  /**\n   * Open an existing stored session for `read` or single-writer `write`.\n   * @param id - the stored session to open.\n   * @param access - `read` (no ownership) or `write` (atomic in-process claim).\n   * @param options - optional cancellation.\n   * @returns the open handle.\n   */\n  async open(id: SessionId, access: SessionAccess, options?: SessionPersistenceOpenOptions): Promise<SessionHandle> {\n    options?.signal?.throwIfAborted()\n    await this.ensureRootEncoding()\n    options?.signal?.throwIfAborted()\n    const pending = this.tracker.pendingOf(id)\n    if (access === 'read') {\n      if (pending !== undefined) {\n        return this.tracker.adopt(new JsonlSessionHandle(this, id, pending.header, 'read', { cursor: 0, materialized: false, inheritedEventCount: pending.inheritedEventCount }))\n      }\n      let stored: StoredLog\n      try {\n        stored = await this.requireStoredLog(id, options?.signal)\n      } catch (error: unknown) {\n        if (!(error instanceof JsonlGenerationSourceChangedError)) throw error\n        stored = await this.requireStoredLog(id, options?.signal)\n      }\n      let state: StorageHandleState\n      if (stored.status === 'prepared') {\n        state = {\n          cursor: 0,\n          materialized: true,\n          inheritedEventCount: stored.inheritedEventCount,\n          primed: stored,\n        }\n      } else {\n        state = {\n          cursor: 0,\n          materialized: true,\n          inheritedEventCount: stored.inheritedEventCount,\n        }\n      }\n      return this.tracker.adopt(new JsonlSessionHandle(this, id, stored.meta, 'read', state))\n    }\n    // A pending entry always belongs to an ACTIVE creator handle (close erases\n    // it), so the claim below rejects that case as already owned.\n    this.tracker.claimWrite(id)\n    let lease: SessionWriteLease | undefined\n    try {\n      const resolved = await this.findLog(id, options?.signal)\n      if (resolved === undefined) throw new SessionPersistenceNotFoundError(id)\n      lease = await this.acquireLease(id, undefined, dirname(resolved.currentPath))\n      const prepared = await this.requireStoredLog(id, options?.signal)\n      options?.signal?.throwIfAborted()\n      let stored: CurrentStoredLog\n      if (prepared.status === 'prepared') {\n        stored = await this.publishStoredMigration(id, prepared)\n      } else {\n        stored = prepared\n      }\n      options?.signal?.throwIfAborted()\n      return this.tracker.adopt(new JsonlSessionHandle(this, id, stored.meta, 'write', {\n        cursor: stored.events.length,\n        materialized: true,\n        tornTruncateTo: stored.tornTruncateTo,\n        recoveredTail: stored.recoveredTail,\n        inheritedEventCount: stored.inheritedEventCount,\n        primed: stored,\n      }, lease))\n    } catch (error) {\n      // Free the in-process claim no matter how the kernel-lock release\n      // fares, and keep the original diagnostic: a release failure joins it\n      // instead of replacing it.\n      /* v8 ignore next -- typed backends and fs reject with Error */\n      const failure = error instanceof Error ? error : new Error(String(error))\n      let releaseFailure: Error | undefined\n      try {\n        await lease?.release()\n      } catch (raw: unknown) {\n        /* v8 ignore next -- lock releases reject with Error */\n        releaseFailure = raw instanceof Error ? raw : new Error(String(raw))\n      }\n      this.tracker.releaseClaim(id)\n      if (releaseFailure !== undefined) {\n        throw new AggregateError([failure, releaseFailure], `session \"${id}\": write open failed and its lock release failed`)\n      }\n      throw failure\n    }\n  }\n\n  /**\n   * Flush every active write handle in one durability barrier; see the seam\n   * contract.\n   * @returns resolution once every write handle active at the call has flushed.\n   */\n  flush(): Promise<void> {\n    return this.tracker.flushAll()\n  }\n\n  /**\n   * Observe one stored session without reading its event log.\n   * @param id - the stored session to observe.\n   * @param options - optional cancellation.\n   * @returns the snapshot (`sizeBytes` carries the physical artifact size), or\n   *   `undefined` when the session does not exist.\n   */\n  async stat(\n    id: SessionId,\n    options?: SessionPersistenceStatOptions,\n  ): Promise<SessionPersistenceSnapshot | undefined> {\n    options?.signal?.throwIfAborted()\n    await this.ensureRootEncoding()\n    options?.signal?.throwIfAborted()\n    const pending = this.tracker.pendingOf(id)\n    if (pending !== undefined) {\n      return { header: pending.header, revision: pending.revision }\n    }\n    const selected = await this.findLog(id, options?.signal)\n    if (selected === undefined) return undefined\n    const metadata = await this.readGenerationHeader(selected, id, options?.signal)\n    if (metadata === undefined) return undefined\n    try {\n      const identity = await stat(selected.sourcePath, { bigint: true })\n      options?.signal?.throwIfAborted()\n      return {\n        ...metadata,\n        revision: selected.sourceVersion < SESSION_FORMAT_VERSION\n          ? SessionPersistenceRevision(`${fileRevision(identity)}:${await this.historicalCorpusRevision(options?.signal)}`)\n          : fileRevision(identity),\n        sizeBytes: Number(identity.size),\n        location: { kind: 'jsonl', path: selected.sourcePath },\n      }\n    } catch (error: unknown) {\n      options?.signal?.throwIfAborted()\n      if (isENOENT(error)) return undefined\n      throw error\n    }\n  }\n\n  /**\n   * List every stored session visible to this process: materialized artifacts\n   * plus this process's created-but-unmaterialized sessions.\n   * @param options - optional cancellation.\n   * @returns one snapshot per session, in no promised order.\n   */\n  async list(options?: SessionPersistenceListOptions): Promise<readonly SessionPersistenceSnapshot[]> {\n    const signal = options?.signal\n    const snapshots: SessionPersistenceSnapshot[] = []\n    const listed = new Set<SessionId>()\n    // Snapshot pending entries BEFORE scanning storage: a session whose first\n    // append lands mid-scan is then still in this snapshot (its artifact may\n    // predate the scan), so create-to-list visibility never has a hole.\n    const pending = [...this.tracker.pendingEntries()]\n    const artifacts = await this.listArtifacts(signal)\n    const corpusRevision = artifacts.some(artifact => artifact.sourceVersion < SESSION_FORMAT_VERSION)\n      ? await this.historicalCorpusRevision(signal) : undefined\n    const statted = settledValues(await settleLimited(this.listLimit, artifacts, async (artifact) => {\n      signal?.throwIfAborted()\n      try {\n        const identity = await stat(artifact.path, { bigint: true })\n        signal?.throwIfAborted()\n        return { artifact, identity }\n      } catch (error: unknown) {\n        signal?.throwIfAborted()\n        if (!isENOENT(error)) throw error\n        return undefined\n      }\n    }))\n    for (const entry of statted) {\n      if (entry === undefined) continue\n      const { artifact, identity } = entry\n      listed.add(artifact.header.id)\n      snapshots.push({\n        header: artifact.header,\n        formatStatus: artifact.formatStatus,\n        revision: artifact.sourceVersion < SESSION_FORMAT_VERSION\n          ? SessionPersistenceRevision(`${fileRevision(identity)}:${corpusRevision}`)\n          : fileRevision(identity),\n        sizeBytes: Number(identity.size),\n        location: { kind: 'jsonl', path: artifact.path },\n      })\n    }\n    for (const [id, entry] of pending) {\n      if (!listed.has(id)) snapshots.push({ header: entry.header, revision: entry.revision })\n    }\n    signal?.throwIfAborted()\n    return snapshots\n  }\n\n  // --- handle-facing storage internals (package-private via the handle class below) ---\n\n  /** Resolve and read one stored log, refusing loudly when the artifact is absent. */\n  private async requireStoredLog(id: SessionId, signal?: AbortSignal): Promise<StoredLog> {\n    const selected = await this.findLog(id, signal)\n    if (selected === undefined) throw new SessionPersistenceNotFoundError(id)\n    if (selected.sourceVersion < SESSION_FORMAT_VERSION) {\n      const sourceRevision = fileRevision(await stat(selected.sourcePath, { bigint: true }))\n      signal?.throwIfAborted()\n      let preparation = this.migrationPreparations.get(id)\n      if (preparation === undefined\n        || preparation.sourcePath !== selected.sourcePath\n        || preparation.sourceRevision !== sourceRevision) {\n        const controller = new AbortController()\n        const promise = this.loadStoredMigration(id, selected, sourceRevision, controller.signal)\n        preparation = {\n          sourcePath: selected.sourcePath,\n          sourceRevision,\n          controller,\n          promise,\n          settled: false,\n          waiters: 0,\n        }\n        this.migrationPreparations.set(id, preparation)\n        const created = preparation\n        const release = (): void => {\n          created.settled = true\n          if (this.migrationPreparations.get(id) === created) {\n            this.migrationPreparations.delete(id)\n          }\n        }\n        void promise.then(release, release)\n      }\n      signal?.throwIfAborted()\n      return this.waitForPreparation(id, preparation, signal)\n    }\n    if (selected.sourceVersion > SESSION_FORMAT_VERSION) {\n      const header = await this.readGenerationHeader(selected, id, signal)\n      /* v8 ignore else -- a readable future header is rejected inside readGenerationHeader. */\n      if (header === undefined) {\n        throw new SessionPersistenceCorruptionError(\n          `session \"${id}\": stored log has a malformed header (raw log: ${selected.sourcePath})`,\n          { cause: new Error('malformed Session header') },\n        )\n      }\n      /* v8 ignore next -- readGenerationHeader rejects every future version. */\n      throw new SessionFormatUnsupportedError(\n        `${sessionFormatVersionRefusal(id, selected.sourceVersion)} (raw log: ${selected.sourcePath})`,\n        { kind: 'jsonl', path: selected.sourcePath },\n      )\n    }\n    const probe = fileRevision(await stat(selected.sourcePath, { bigint: true }))\n    const memoized = this.coldLogMemo.get(id)\n    if (memoized?.status === 'current' && memoized.revision === probe) {\n      this.coldLogMemo.delete(id)\n      this.coldLogMemo.set(id, memoized)\n      return memoized\n    }\n    const current = await readStableJsonlFile(selected.sourcePath, signal)\n    return this.decodeStoredLog(\n      selected.sourcePath,\n      id,\n      current.bytes,\n      fileRevision(current.identity),\n      signal,\n    )\n  }\n\n  /** Probe the memo and otherwise decode one historical generation under backend cancellation. */\n  private async loadStoredMigration(\n    id: SessionId,\n    selected: ResolvedJsonlGeneration,\n    sourceRevision: PersistenceRevision,\n    signal: AbortSignal,\n  ): Promise<PreparedStoredLog> {\n    signal.throwIfAborted()\n    const memoized = this.coldLogMemo.get(id)\n    if (memoized?.status === 'prepared' && memoized.revision === sourceRevision) {\n      try {\n        await memoized.validateRelatedSources()\n      } catch (error: unknown) {\n        this.coldLogMemo.delete(id)\n        throw this.generationFailure(id, selected, error)\n      }\n      this.coldLogMemo.delete(id)\n      this.coldLogMemo.set(id, memoized)\n      return memoized\n    }\n    return this.prepareStoredMigration(id, selected, signal)\n  }\n\n  /** Await shared preparation for one caller and abort it only after its last waiter leaves. */\n  private async waitForPreparation(\n    id: SessionId,\n    preparation: MigrationPreparation,\n    signal?: AbortSignal,\n  ): Promise<PreparedStoredLog> {\n    preparation.waiters += 1\n    try {\n      return await waitWithAbort(preparation.promise, signal)\n    } finally {\n      preparation.waiters -= 1\n      if (preparation.waiters === 0 && !preparation.settled) {\n        /* v8 ignore else -- a newer selected source may already own this id's preparation slot. */\n        if (this.migrationPreparations.get(id) === preparation) {\n          this.migrationPreparations.delete(id)\n        }\n        preparation.controller.abort()\n      }\n    }\n  }\n\n  /** Decode one historical generation without publishing a successor. */\n  private async prepareStoredMigration(\n    id: SessionId,\n    selected: ResolvedJsonlGeneration,\n    signal: AbortSignal,\n  ): Promise<PreparedStoredLog> {\n    let prepared: Awaited<ReturnType<typeof prepareJsonlMigration>>\n    let validateRelatedSources: () => Promise<void>\n    try {\n      const children = async () => (await this.listArtifacts(signal))\n        .filter(source => source.header.origin === 'subagent' && source.header.parentSession === id)\n      const sources = await children()\n      const related = await prepareCatalogFacts(id, sources, this.compression, signal)\n      for (const failure of related.failures) {\n        this.ctx.logger.warn(`${this.name}: session \"${id}\" catalog retained a child with unknown descriptor (raw log: ${failure.path}): ${String(failure.error)}`)\n      }\n      const membership = sources.map(source => source.path).sort()\n      validateRelatedSources = async () => {\n        const current = (await children()).map(source => source.path).sort()\n        const before = new Set(membership)\n        const after = new Set(current)\n        const changed = current.find(path => !before.has(path)) ?? membership.find(path => !after.has(path))\n        if (changed !== undefined) throw new JsonlGenerationSourceChangedError(changed)\n        await related.validate()\n      }\n      prepared = await prepareJsonlMigration({\n        sourcePath: selected.sourcePath,\n        sourceVersion: selected.sourceVersion,\n        currentPath: selected.currentPath,\n        compression: this.compression,\n        format: {\n          ...this.generationFormat,\n          createRestore: header => createSessionFormatCatalogWithChildren(related.facts).createRestore(header, {\n            recovery: 'recoverable', validation: 'transformed',\n          }),\n        },\n        validateRelatedSources,\n        verifyCurrentFile: verifyCurrentGenerationInWorker,\n        validateHistoricalHeader: headerValue => this.validateSourceIdentity(\n          selected,\n          headerValue,\n          id,\n          signal,\n        ),\n        signal,\n      })\n    } catch (error: unknown) {\n      throw this.generationFailure(id, selected, error)\n    }\n    const meta = this.currentHeader(prepared.artifact.header)\n    assertStoredId(id, meta)\n    const events = prepared.artifact.events as SessionEvent[]\n    validateStoredEvents(meta, events, { kind: 'jsonl', path: selected.sourcePath })\n    const stored: PreparedStoredLog = {\n      status: 'prepared',\n      validateRelatedSources,\n      meta,\n      ...freezeStoredEvents(events),\n      tornTruncateTo: undefined,\n      recoveredTail: [],\n      inheritedEventCount: SessionLogOffset(prepared.artifact.inheritedEventCount),\n      revision: fileRevision(prepared.sourceIdentity),\n      publication: { source: selected, value: prepared },\n    }\n    this.memoizeStoredLog(id, stored)\n    return stored\n  }\n\n  /** Publish a prepared historical log before granting write access. */\n  private async publishStoredMigration(id: SessionId, stored: PreparedStoredLog): Promise<CurrentStoredLog> {\n    const migration = stored.publication\n    let identity: JsonlPhysicalIdentity\n    try {\n      identity = await migration.value.publish()\n    } catch (error: unknown) {\n      /* v8 ignore else -- a newer preparation may have replaced this stale cache entry. */\n      if (this.coldLogMemo.get(id) === stored) this.coldLogMemo.delete(id)\n      throw this.generationFailure(id, migration.source, error)\n    }\n    const published: CurrentStoredLog = {\n      status: 'current',\n      meta: stored.meta,\n      eventState: stored.eventState,\n      events: stored.events,\n      tornTruncateTo: stored.tornTruncateTo,\n      recoveredTail: stored.recoveredTail,\n      inheritedEventCount: stored.inheritedEventCount,\n      revision: fileRevision(identity),\n    }\n    this.memoizeStoredLog(id, published)\n    return published\n  }\n\n  /** Translate generation-layer failures into the persistence seam's error vocabulary. */\n  private generationFailure(\n    id: SessionId,\n    selected: ResolvedJsonlGeneration,\n    error: unknown,\n  ): Error {\n    if (error instanceof JsonlGenerationUnsupportedMigrationError) {\n      return new SessionFormatUnsupportedError(\n        `${error.message}; source v${error.fromVersion} artifact remains unchanged (raw log: ${selected.sourcePath})`,\n        { kind: 'jsonl', path: selected.sourcePath },\n      )\n    }\n    if (error instanceof JsonlGenerationSourceChangedError) return error\n    if (error instanceof SessionFormatUnsupportedError\n      || error instanceof SessionPersistenceCorruptionError\n      || isErrnoException(error)\n      || error instanceof DOMException && error.name === 'AbortError') return error\n    return new SessionPersistenceCorruptionError(\n      `session \"${id}\": stored log is corrupt: ${String(error)} (raw log: ${selected.sourcePath})`,\n      { cause: error },\n    )\n  }\n\n  /**\n   * Read, parse, and validate one stored log as the current logical prefix.\n   * @param path - the artifact file to read.\n   * @param expectedId - the session identity the artifact must carry.\n   * @param signal - optional cancellation for the stat/read/decode work.\n   * @returns the validated stored log with any torn-tail truncation point.\n   */\n  async readStoredLog(path: string, expectedId: SessionId, signal?: AbortSignal): Promise<CurrentStoredLog> {\n    signal?.throwIfAborted()\n    const probe = fileRevision(await stat(path, { bigint: true }))\n    const memoized = this.coldLogMemo.get(expectedId)\n    if (memoized?.status === 'current' && memoized.revision === probe) {\n      this.coldLogMemo.delete(expectedId)\n      this.coldLogMemo.set(expectedId, memoized)\n      return memoized\n    }\n    const { bytes, identity } = await readStableJsonlFile(path, signal)\n    return this.decodeStoredLog(path, expectedId, bytes, fileRevision(identity), signal)\n  }\n\n  /** Decode and memoize one already-stable current physical snapshot. */\n  private async decodeStoredLog(\n    path: string,\n    expectedId: SessionId,\n    buffer: Buffer,\n    revision: PersistenceRevision,\n    signal?: AbortSignal,\n  ): Promise<CurrentStoredLog> {\n    let parsed: {\n      meta: SessionHeader\n      inheritedEventCount: SessionLogOffsetType\n      events: SessionEvent[]\n      tornTruncateTo: number | undefined\n      recoveredTail: SessionEvent[]\n    }\n    try {\n      if (this.compression === 'zstd') {\n        parsed = await this.readZstdPrefix(buffer, signal)\n      } else {\n        signal?.throwIfAborted()\n        const { meta, inheritedEventCount, events, committedBytes } = scanLog(buffer)\n        signal?.throwIfAborted()\n        parsed = {\n          meta,\n          inheritedEventCount,\n          events,\n          tornTruncateTo: committedBytes < buffer.byteLength ? committedBytes : undefined,\n          // A torn raw tail is one incomplete JSONL line; it holds no complete\n          // record to recover.\n          recoveredTail: [],\n        }\n      }\n    } catch (error: unknown) {\n      signal?.throwIfAborted()\n      // A parse-time format refusal predates any SessionHeader, so attach the\n      // artifact this read actually refused; every other parse failure is\n      // committed bytes the decoder cannot interpret — damage, classified for\n      // the seam's stable error vocabulary.\n      if (error instanceof SessionFormatUnsupportedError) {\n        throw new SessionFormatUnsupportedError(`${error.message} (raw log: ${path})`, { kind: 'jsonl', path })\n      }\n      throw new SessionPersistenceCorruptionError(`session \"${expectedId}\": stored log is corrupt: ${String(error)} (raw log: ${path})`, { cause: error })\n    }\n    signal?.throwIfAborted()\n    await this.assertStoredIdentity(path, SESSION_FORMAT_VERSION, parsed.meta, expectedId, signal)\n    signal?.throwIfAborted()\n    assertStoredId(expectedId, parsed.meta)\n    const location = this.locate(parsed.meta)\n    validateStoredEvents(parsed.meta, parsed.events, location)\n    const { events, ...rest } = parsed\n    const stored: CurrentStoredLog = {\n      status: 'current',\n      ...rest,\n      ...freezeStoredEvents(events),\n      revision,\n    }\n    this.memoizeStoredLog(expectedId, stored)\n    return stored\n  }\n\n  /** Insert one parsed log into the bounded handoff cache. */\n  private memoizeStoredLog(id: SessionId, stored: StoredLog): void {\n    this.coldLogMemo.delete(id)\n    this.coldLogMemo.set(id, stored)\n    for (const oldest of this.coldLogMemo.keys()) {\n      if (this.coldLogMemo.size <= COLD_LOG_MEMO_MAX_ENTRIES) break\n      this.coldLogMemo.delete(oldest)\n    }\n  }\n\n  /**\n   * Resolve a session's current-generation log path.\n   * @param id - the stored session to locate.\n   * @param signal - optional cancellation for the directory scans.\n   * @returns the current artifact path, or `undefined` while only a historical generation exists.\n   */\n  async resolveCurrentLog(id: SessionId, signal?: AbortSignal): Promise<string | undefined> {\n    await this.ensureRootEncoding()\n    signal?.throwIfAborted()\n    const selected = await this.findLog(id, signal)\n    if (selected === undefined) return undefined\n    if (selected.sourceVersion === SESSION_FORMAT_VERSION) return selected.sourcePath\n    if (selected.sourceVersion < SESSION_FORMAT_VERSION) return undefined\n    const reason = sessionFormatVersionRefusal(id, selected.sourceVersion)\n    throw new SessionFormatUnsupportedError(\n      `${reason} (raw log: ${selected.sourcePath})`,\n      { kind: 'jsonl', path: selected.sourcePath },\n    )\n  }\n\n  /**\n   * Durably append one validated batch; lazily materializes on the first write.\n   * @param header - the session's stored header.\n   * @param events - the validated contiguous batch, in seq order.\n   * @param isMaterialized - whether the session already has a durable artifact.\n   * @param inheritedEventCount - the exact fork-inherited prefix length written into a materializing header line.\n   */\n  async persistBatch(\n    header: SessionHeader,\n    events: readonly SessionEvent[],\n    isMaterialized: boolean,\n    inheritedEventCount: SessionLogOffsetType,\n  ): Promise<void> {\n    this.coldLogMemo.delete(header.id)\n    await this.ensureRootEncoding()\n    if (isMaterialized) {\n      await this.appendLines(header, events)\n    } else {\n      await this.materialize(header, inheritedEventCount, events)\n      this.tracker.materialized(header.id)\n    }\n  }\n\n  /**\n   * Materialize a header-only artifact for an explicitly durable empty session.\n   * @param header - the session's stored header.\n   * @param inheritedEventCount - the exact fork-inherited prefix length written into the header line.\n   */\n  async persistHeader(header: SessionHeader, inheritedEventCount: SessionLogOffsetType): Promise<void> {\n    this.coldLogMemo.delete(header.id)\n    await this.ensureRootEncoding()\n    await this.materialize(header, inheritedEventCount, [])\n    this.tracker.materialized(header.id)\n  }\n\n  /**\n   * Truncate a torn physical tail durably before this session's first new append.\n   * @param header - the session's stored header.\n   * @param truncateTo - the byte offset the artifact is truncated to.\n   */\n  async truncateTornTail(header: SessionHeader, truncateTo: number): Promise<void> {\n    this.coldLogMemo.delete(header.id)\n    await this.repair(header, truncateTo)\n    this.ctx.logger.warn(`${this.name}: session \"${header.id}\" recovered from a torn tail; incomplete tail bytes were discarded`)\n  }\n\n  /**\n   * Whether this process still tracks a created-but-unmaterialized session.\n   * @param id - the session to test.\n   * @returns true while the pending entry exists.\n   */\n  hasPendingSession(id: SessionId): boolean {\n    return this.tracker.hasPending(id)\n  }\n\n  /**\n   * Release one handle's backend bookkeeping on close.\n   * @param handle - the closing handle.\n   * @param materialized - whether the session reached durable storage.\n   */\n  releaseHandle(handle: JsonlSessionHandle, materialized: boolean): void {\n    this.tracker.release(handle, materialized)\n  }\n\n  /**\n   * Acquire the session directory's kernel write lock; the kernel holds it\n   * until the handle's close releases the descriptor, including on process death.\n   * @param id - the session the lock guards.\n   * @param cwd - header cwd used to derive the directory for